(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["moe"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-monomoe-fused-kernel"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-1\">一 · 一次线上抖动：小 batch 下五个 kernel 的账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-2\">二 · 它到底解决什么：把五段并成一段常驻</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-3\">三 · 它不解决什么：三条明确的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-4\">四 · 适用判据：三个可测的信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-5\">五 · 代价的另一面：复杂度与可观测性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-6\">六 · 融合大核救不了的那一类 decode：边界、失效条件与系统代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-7\">七 · 常驻 SM 与全局队列取 micro-batch</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-8\">八 · TMA 异步预取量化权重到 shared memory</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-9\">九 · shared memory 内反量化与 token 重排</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-10\">十 · tcgen05 MMA 与寄存器内 combine</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-11\">十一 · 写回与循环续取：收益边界与退化定位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-12\">十二 · 融合核的边界条件：收益从哪来、又在哪失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-13\">十三 · 时延上界的逐项拆解：从 $T_{\\text{decode}}$ 到 $T_{\\text{fused}}$</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-14\">十四 · 带宽项与计算项谁主导：一个可判定的判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-15\">十五 · 伪代码：把三步机制落到可实现结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-16\">十六 · 流水重叠的定量条件：TMA 与 tcgen05 的速率匹配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-17\">十七 · 失败模式的公式化定位与移植成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-18\">十八 · 融合大核的失效边界与系统代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-19\">十九 · 请求形态：小 batch 才是主场</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-20\">二十 · 长度分布：短请求密集才喂得饱队列</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-21\">二十一 · 并发与批大小：micro-batch 是调度单位，不是越大越好</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-22\">二十二 · 负载不对时的退化路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-23\">二十三 · 配方与容量规划的接口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-24\">二十四 · 负载配方：小批解码的甜区与越界后的反噬</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-25\">二十五 · 硬件档位与 SM 常驻预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-26\">二十六 · 并行拓扑：EP 组内融合、组间走网络</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-27\">二十七 · 量化方案：权重 NVFP4/INT4，激活侧留出接口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-28\">二十八 · KV 策略：与专家权重共享显存时的配额</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-29\">二十九 · 调度参数与可复现配置清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-30\">三十 · 融合大核的适用边界：什么配置下它真的省时</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-31\">三十一 · 融合核的代价结构：从“省掉什么”到“多出什么”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-32\">三十二 · 带宽账：权重字节是分子，micro-batch 是分母</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-33\">三十三 · 通信账：融合核把 All-to-All 的边界推到 kernel 之外</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-34\">三十四 · 功耗与占用：常驻 SM 的代价不是免费的</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-35\">三十五 · 尾延迟：融合核把抖动集中到一个不可分割的段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-36\">三十六 · 规模上去以后哪里先崩：一条按规模排序的崩溃链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-37\">三十七 · 精度失效的三条路径与定点观测</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-38\">三十八 · OOM 与 shared memory 溢出的判别</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-39\">三十九 · 批抖动与路由不均的耦合诊断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-40\">四十 · 尾延迟尖刺的定位顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-41\">四十一 · 监控面与回滚判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-42\">四十二 · 跨架构移植与调试成本的工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-43\">四十三 · 融合核的失效边界：从精度漂移、显存溢出到尾延迟尖刺</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-44\">四十四 · 决策轴：先分清“谁在等谁”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-45\">四十五 · 对照表：四类同族算法的适用条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-46\">四十六 · 选型伪代码：按序排除而非按分排序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-47\">四十七 · 代价对照：延迟、吞吐、显存、带宽与功耗</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-48\">四十八 · 混合策略：把融合限制在它赢的那一段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-49\">四十九 · 工程判断：三条硬线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-monomoe-fused-kernel-sec-50\">五十 · 与相邻算法对照：同族算法怎么选</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:499px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 499.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"417.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">mega-kernel 启动后常驻 SM，从全局队列取 micro-bat…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"417.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">TMA 异步把激活专家的量化权重从 HBM 加载到 shared memo…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"417.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">在 shared memory 内完成反量化与 token 重排，直接喂给…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"417.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">MMA 结果在寄存器内按路由权重累加，combine 不落 HBM</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"417.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">输出写回全局显存，kernel 继续处理下一 micro-batch，避免…</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-monomoe-fused-kernel-sec-1\">一 · 一次线上抖动：小 batch 下五个 kernel 的账</h3>\n<p>某个已上线的量化 MoE 解码服务在夜间低峰期出现了一批 P99 尾延迟尖刺：吞吐指标看着正常，单请求时延却成倍拉长，且只在并发请求数很低的时段出现。抓取 trace 后发现，一个 decode step 被切成了五段：路由（router 打分与 top-k）、dispatch（按专家重排 token）、反量化（把 NVFP4/INT4 权重还原成计算精度）、分组 GEMM、combine（按路由权重加权求和）。每段都是一个独立 kernel，每段都要把中间缓冲写回 HBM、再由下一段读回来。高峰期这些开销被较大的 batch 摊薄，低峰期则原形毕露——路由结果、重排后的 token、反量化后的权重、GEMM 的部分和，全都在 HBM 上走了一遍往返。</p>\n<p>把这段路径写成时间账：设单个 kernel 的固定启动与同步开销为 $\\epsilon_{\\text{launch}}$，中间缓冲往返字节数为 $B_{\\text{mid}}$，则多 kernel 流水的一步时延近似为</p>\n<div class=\"formula\">$$T_{\\text{multi}} \\approx \\sum_{k=1}^{5}\\left(\\frac{B_{\\text{mid},k}}{\\text{BW}_{\\text{HBM}}} + \\epsilon_{\\text{launch},k}\\right) + T_{\\text{GEMM}}$$</div>\n<p>在小 batch 下 $T_{\\text{GEMM}}$ 本身很短，前两项反而成了主项——给定事实明确指出，此时 kernel launch 与 HBM 往返开销占比超过 50%。这不是某个 kernel 写得不好，而是切分方式与低并发场景的结构性错配：五段串行，段与段之间是硬同步点，GPU 在每次同步前后都要空转等缓冲落盘。事故的工程含义很直接：解码服务的 SLO 由尾延迟定义，而尾延迟恰恰落在 launch 开销占比最高的低并发区间。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-2\">二 · 它到底解决什么：把五段并成一段常驻</h3>\n<p>这个算法的靶心是“量化 MoE decode 的多 kernel 切分税”。做法是把路由之后的 dispatch、NVFP4/INT4 反量化、分组 GEMM、combine 融合为一个 persistent mega-kernel：kernel 启动后常驻 SM，从全局队列逐个取 micro-batch 的路由结果，处理完一个继续取下一个，不再重复 launch。中间结果——重排后的 token、反量化后的权重片段、MMA 的部分和——留在 shared memory 与寄存器里，不落 HBM。权重加载走 TMA 异步搬运，与 tcgen05 异步 MMA 形成流水重叠；MMA 结果在寄存器内直接按路由权重累加，combine 阶段被吸收进 epilogue，只有最终输出写回全局显存。</p>\n<p>融合后的时延模型变为</p>\n<div class=\"formula\">$$T_{\\text{fused}} \\approx \\max\\left(\\frac{B_w}{\\text{BW}_{\\text{HBM}}},\\ T_{\\text{MMA}}\\right) + T_{\\text{epilogue}}$$</div>\n<p>其中 $B_w$ 是激活专家的量化权重字节数，$T_{\\text{MMA}}$ 是矩阵乘时间，$T_{\\text{epilogue}}$ 是寄存器累加与写回时间。注意 max 取代了求和：权重搬运与 MMA 被流水重叠，二者取较慢者，而 $\\epsilon_{\\text{launch}}$ 在 persistent 结构下趋近于零。给定事实给出的收益区间是小 batch decode 时延降低 30–50%，带宽受限场景下 GPU 利用率接近峰值。这个模型的诊断价值在于它指明了优化方向：若 $B_w/\\text{BW}_{\\text{HBM}}$ 是瓶颈，说明该算法正处在最舒服的适用区间；若 $T_{\\text{MMA}}$ 反超，融合的边际收益就开始衰减。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-3\">三 · 它不解决什么：三条明确的边界</h3>\n<p>第一条边界是 batch 规模。收益随 batch 增大而下降：大 batch 下 GEMM 计算占比上升，launch 开销被摊薄，多 kernel 流水本身的效率并不差，而 mega-kernel 为融合付出的寄存器压力与调度约束反而成为负担。因此它不是高吞吐预填或大 batch 解码的答案，那些场景该由别的路径承担。</p>\n<p>第二条边界是路由策略本身。容量因子路由与令牌丢弃、专家选择路由这些主题决定了 token 如何落到专家上，本算法只消费路由结果，不改变路由决策。路由分布若剧烈倾斜，mega-kernel 内各专家的负载会失衡，但这不是融合能修的——它属于路由层的容量设计问题。</p>\n<p>第三条边界是显存布局。分页 KV 与专家权重共存的显存问题、分离式专家并行的 All-to-All 调度，都是本算法之外的话题；mega-kernel 假设激活专家的量化权重可以被 TMA 从 HBM 搬进 shared memory，它优化的是搬运与计算的 overlap，而不是权重该放在哪、跨节点怎么传。此外它不涉及激活量化的具体方案，材料未给出激活量化细节，只明确权重为 NVFP4/INT4 格式。</p>\n<p>还有一条隐性边界值得写进工程判断：shared memory 容量。反量化与 token 重排都在 shared memory 内完成，一旦容量不足就会溢出到 HBM，融合收益被直接抵消——这是该算法最脆弱的物理约束，也是选型时必须先算的一笔账。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-4\">四 · 适用判据：三个可测的信号</h3>\n<p>判断一个服务是否落在适用区间，不需要猜，看三个信号即可。其一是 trace 上单步 decode 的 kernel 间隙占比：若五个 kernel 之间的空隙与缓冲往返合计超过一半，融合的收益空间就已具备。其二是 batch 分布：micro-batch 逐个从全局队列取的负载配方，正对应低并发、时延敏感的解码服务；给定事实未给出具体批大小与 SLO 数值，因此判据应落在“launch 开销是否被摊薄”这一可观测事实上，而非某个阈值数字。其三是瓶颈位置：用 $B_w/\\text{BW}_{\\text{HBM}}$ 与 $T_{\\text{MMA}}$ 的比较判断当前是带宽受限还是算力受限，前者才是本算法的主场。</p>\n<p>举个具体例子：一个夜间低峰的解码实例，并发请求少、每步只处理少量 token，五个 kernel 串行且中间缓冲全走 HBM，此时 $T_{\\text{multi}}$ 中求和项占主导；换成 mega-kernel 后，权重经 TMA 搬入 shared memory 与 tcgen05 MMA 重叠，combine 在寄存器内完成，时延模型退化为 max 形式，尾延迟尖刺消失。反过来，若同一实例在白天高并发下运行，GEMM 占比上升，融合带来的 30–50% 时延收益会被稀释，此时更该关注的是分组 GEMM 本身的效率与专家并行调度。</p>\n<table class=\"mini\"><thead><tr><th>信号</th><th>落在适用区</th><th>落在边界外</th></tr></thead><tbody><tr><td>kernel 间隙与缓冲往返占比</td><td>超过一半</td><td>被大 batch 摊薄至次要项</td></tr><tr><td>batch 形态</td><td>小 batch、micro-batch 逐个取</td><td>大 batch 预填或高吞吐解码</td></tr><tr><td>瓶颈位置</td><td>$B_w/\\text{BW}_{\\text{HBM}}$ 主导</td><td>$T_{\\text{MMA}}$ 主导</td></tr><tr><td>shared memory 余量</td><td>容得下反量化与重排</td><td>溢出到 HBM，收益抵消</td></tr></tbody></table>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-5\">五 · 代价的另一面：复杂度与可观测性</h3>\n<p>融合不是免费的。mega-kernel 需手写 PTX/CUDA 并针对 SM100/SM103 的 TMA 与 tcgen05 指令定制，跨架构移植成本极高——这套代码绑定的是 Blackwell 的特定指令集，换一代硬件几乎等于重写。更麻烦的是可观测性：五段合一之后，原本可以用 nsys 逐段打点的边界消失了，调试与 profiling 困难；路由分布突变时，无法定位是反量化、重排还是 MMA 流水哪一段退化，只能整体怀疑。这与多 kernel 流水形成鲜明对照——后者慢，但每一段的账都算得清。</p>\n<p>工程上的对冲手段是在 mega-kernel 内部保留轻量计时点与分阶段计数器，把“不可见”重新变成“可见”，代价是少量寄存器与指令开销。另一条对冲是保留多 kernel 路径作为回退：当路由分布异常或 shared memory 压力过大时切回分段实现，牺牲时延换取可诊断性。这两条都不是算法本身的机制，而是把它放进生产系统时必须配套的运维设计——给定事实把“调试与 profiling 困难”列为失败模式，正说明这一代价与性能收益同等重要。</p>\n<p>最后落到一个具体判断上：若你的解码服务在低峰期出现无法用吞吐解释的尾延迟，且 trace 显示五个 kernel 的间隙与 HBM 往返占据主导，那么融合大核是正解；但若团队没有手写 PTX 的能力、也没有为不可观测性准备回退路径，那么先修分段实现的缓冲复用与 launch 合并，比直接上 mega-kernel 更稳。适用边界不在算法论文里，而在你的 trace、batch 分布与 shared memory 余量这三笔账里。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-6\">六 · 融合大核救不了的那一类 decode：边界、失效条件与系统代价</h3>\n<p>先把事故讲清楚：一套线上量化 MoE 解码服务，权重是 NVFP4/INT4，batch 一直开得很小（连续批处理下每个 micro-batch 只有零星几条请求）。某天路由分布发生突变——原本集中在少数专家的 token 被摊到长尾专家上，p99 首 token 时延突然抬升，而 GPU 利用率曲线几乎没动。值班工程师按常规路径排查：先看路由 kernel，正常；再看 dispatch，正常；反量化 kernel 的耗时看起来也没变；分组 GEMM 的 SM 占用甚至更高了。五个 kernel 各自“健康”，端到端却退化了。真正的原因是每个 kernel 都在读写自己的中间缓冲，专家变分散后中间张量的形状与地址分布变碎，HBM 往返次数上升，而 kernel launch 与这些往返在小 batch 下本来就占掉超过一半的时间——这部分开销被切碎分摊到五个 kernel 的计时里，任何一个单 kernel 的 profile 都看不见它。这正是把路由、dispatch、NVFP4/INT4 反量化、分组 GEMM、combine 融合成单个 persistent mega-kernel 的动机：中间结果留在 shared memory 与寄存器，combine 不落 HBM，micro-batch 从全局队列逐个取，launch 开销趋近于零。</p>\n<p>但它解决的问题有明确形状。融合后的时延近似为</p>\n<div class=\"formula\">$$T_{\\text{fused}} \\approx \\max\\left(\\frac{B_w}{\\text{BW}_{\\text{HBM}}},\\ T_{\\text{MMA}}\\right) + T_{\\text{epilogue}}$$</div>\n<p>其中 $B_w$ 是权重字节数，$T_{\\text{MMA}}$ 是矩阵乘时间，$T_{\\text{epilogue}}$ 是寄存器累加与写回时间。这个式子的含义是：只有当权重加载（带宽受限）或 MMA 二者之一真正主导时，融合才有意义；一旦 $T_{\\text{MMA}}$ 随 batch 增大而上升并超过带宽项，launch 开销被摊薄，多 kernel 流水反而更容易做负载均衡与流水编排。所以适用边界是“小 batch、带宽受限的量化 MoE decode”，收益随 batch 增大而单调下降。反过来说，它不解决大 batch 高吞吐场景的 GEMM 效率问题，也不解决专家并行下的跨卡 dispatch 通信——mega-kernel 融合的是单卡内的阶段，跨节点 all-to-all 仍在核外。</p>\n<p>失效条件比适用边界更值得写进值班手册。第一，shared memory 容量不足时，反量化与 token 重排会溢出到 HBM，融合收益被直接抵消，此时大核退化成“一个 launch 里塞了五次 HBM 往返”，比多 kernel 更难解释。第二，路由分布突变时无法定位退化阶段：五个 kernel 时有五个计时器，融合后只有一个，工程师只能看到总时延上升，却分不清是 TMA 权重加载变慢、反量化在 shared memory 里 bank 冲突，还是 combine 的寄存器压力导致 occupancy 下降。第三，mega-kernel 需手写 PTX/CUDA 并绑定 SM100/SM103 的 TMA 与 tcgen05 指令，跨架构移植成本极高——同一份代码在别的加速器上不是“慢一点”，而是不存在。第四，激活量化细节在材料中未给出，若激活量化与权重反量化的数值路径在融合后被压进同一条流水，精度回归的定位难度也随之上升。</p>\n<table class=\"mini\"><thead><tr><th>场景</th><th>融合大核的收益</th><th>主要代价/风险</th></tr></thead><tbody><tr><td>小 batch、带宽受限、专家集中</td><td>消除 launch 与 HBM 往返，时延降 30–50%</td><td>实现复杂度高，调试困难</td></tr><tr><td>路由分布突变、长尾专家增多</td><td>收益不确定，中间缓冲变碎</td><td>无法定位退化阶段</td></tr><tr><td>shared memory 不足</td><td>收益被溢出抵消</td><td>退化为隐式多次 HBM 往返</td></tr><tr><td>大 batch、计算占比上升</td><td>收益随 batch 增大而下降</td><td>多 kernel 流水更易均衡</td></tr></tbody></table>\n<p>工程判断落在部署配方上：这套方案只对 SM100/SM103 的 TMA 与 tcgen05 定制、权重为 NVFP4/INT4 的推理栈成立，且必须配一套能按 micro-batch 观测的旁路指标（队列深度、每 micro-batch 的权重字节数、epilogue 写回量），否则融合后的事故只能靠回滚定位。它与多 kernel 流水的差别不在“谁更快”，而在“谁在什么 batch 区间更快、以及出问题时谁更容易被拆开看”。</p>\n<h3 id=\"alg-monomoe-fused-kernel-sec-7\">七 · 常驻 SM 与全局队列取 micro-batch</h3>\n<p>mega-kernel 的第一步不是计算，而是“占住 GPU”。启动时按 SM 数量与每 SM 可用 shared memory 规划出固定数量的常驻 block，每个 block 绑定自己的 TMEM 分区与 TMA 描述符，随后进入一个持久循环。循环顶部从全局队列取一个 micro-batch 的路由结果——注意取的是路由结果而非原始 token，路由已在更早的轻量 kernel 中完成，队列里放的是按专家分组后的 token 索引、路由权重、以及该 micro-batch 的 token 计数。这一步的输入是队列条目，输出是一份被 block 私有化的 dispatch 描述符，代价是一次全局内存读加一次队列同步，量级在微秒级，但它的意义在于把原本每个 kernel 都要付的 launch 开销压缩成一次。</p>\n<p>把这一步放进时延模型里看：未融合时，路由、dispatch、反量化、分组 GEMM、combine 各自 launch，每次 launch 与 kernel 边界的 HBM 往返在小 batch 下占比超过 50%。融合后，这部分被折叠进持久循环的循环开销，只剩队列同步与描述符读取。用公式表达，单 micro-batch 的时延下限由权重字节数与显存带宽、以及 MMA 时间共同决定：</p>\n<div class=\"formula\">$$T_{\\text{fused}} \\approx \\max\\left(\\frac{B_w}{\\text{BW}_{\\text{HBM}}},\\ T_{\\text{MMA}}\\right) + T_{\\text{epilogue}}$$</div>\n<p>其中 $B_w$ 是该 micro-batch 激活专家的量化权重字节数。工程含义很直接：小 batch 时 $B_w/\\text{BW}_{\\text{HBM}}$ 主导，融合省下的是反复搬运中间缓冲的带宽；大 batch 时 $T_{\\text{MMA}}$ 主导，融合收益被摊薄。举例：一个 micro-batch 只命中少数专家、每专家权重为 NVFP4 格式，权重加载量远小于激活与中间缓冲的往返量，此时队列取数与权重预取的重叠质量直接决定这一步是否“免费”。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-8\">八 · TMA 异步预取量化权重到 shared memory</h3>\n<p>拿到 dispatch 描述符后，block 立刻为本次命中的每个专家发起 TMA 异步拷贝，把该专家的 NVFP4/INT4 量化权重从 HBM 搬进 shared memory 的权重槽。输入是专家权重在显存中的基址与量化块布局，输出是 shared memory 中按 MMA 期望的 swizzle 排布的权重 tile。关键在于 TMA 是异步的：拷贝发起后 block 不等待，而是转去处理上一个 micro-batch 尚未完成的 MMA 尾段，或者为下一个专家槽准备 token 重排。这样权重加载与 tcgen05 MMA 形成流水重叠，把“搬权重”的时间藏进“算”的时间里。</p>\n<p>这一步的代价是 shared memory 容量与 TMA 事务粒度。权重槽数量受每 SM shared memory 上限约束，槽太少则流水深度不足、TMA 与 MMA 无法重叠；槽太多则留给反量化与 token 重排的空间被挤掉。失败模式正在这里：shared memory 容量不足时，反量化与 token 重排会溢出到 HBM，融合收益被抵消。另一个代价是 TMA 描述符的定制成本——SM100/SM103 的 TMA 指令需要手写 PTX/CUDA 并针对张量布局定制，跨架构移植成本极高。举例：当路由分布突变导致某专家被大量 token 命中，其权重 tile 需要连续多次 TMA 拷贝，若槽位规划未考虑这种偏斜，流水会在该专家上出现气泡，表现为这一步的等待时间上升而非 MMA 时间上升。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-9\">九 · shared memory 内反量化与 token 重排</h3>\n<p>权重 tile 落地后，在 shared memory 内完成两件事：把 NVFP4/INT4 的微缩放量化权重反量化回可参与 MMA 的数值格式，以及把按专家分组打散的 token 重排成 MMA 需要的行主序 tile。输入是量化权重 tile 与 dispatch 描述符中的 token 索引，输出是可直接喂给 tcgen05 MMA 的权重与激活 tile。这一步不落 HBM，全部在片上完成，是融合的核心价值所在——未融合时反量化是一个独立 kernel，要把反量化结果写回 HBM 再被 GEMM 读回，两次往返全被省掉。</p>\n<p>代价集中在算力与片上带宽的争用。反量化本身是逐元素的缩放乘加，token 重排是带索引的 gather/scatter，两者都吃 shared memory 带宽，且与 TMA 写入权重槽争同一块片上存储。工程判断是：反量化应尽量与 MMA 的消费节奏对齐，按 MMA 的 K 维步进分块反量化，而不是一次性反量化整个专家权重，否则片上缓冲峰值会把槽位挤爆。举例：一个专家权重 tile 反量化后体积膨胀数倍（NVFP4 到高精度中间格式），若一次性展开，shared memory 占用会超过单槽预算，迫使流水降深度；分块反量化则把峰值压到单个 MMA 步进所需，代价是反量化指令与 MMA 指令的交错调度更复杂。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-10\">十 · tcgen05 MMA 与寄存器内 combine</h3>\n<p>反量化与重排完成的 tile 直接进入 tcgen05 异步 MMA。输入是 shared memory 中的权重与激活 tile，输出是累加在 TMEM 中的部分和。这里有两个融合点：其一，MMA 是异步的，发起后 block 可以继续为下一个 K 步进准备数据，形成“反量化—MMA—再反量化”的软件流水；其二，MMA 结果不写回 HBM 做 combine，而是在寄存器/TMEM 内按路由权重累加。输入的路由权重来自 dispatch 描述符，输出是该 token 在该专家上的加权贡献。</p>\n<p>这一步的代价是 TMEM 容量与累加精度。TMEM 分区有限，同时驻留的累加器数量决定了能并行处理多少 token-专家对；累加在寄存器内完成意味着 combine 的路由权重乘法与加法必须与 MMA 尾段紧密耦合，任何额外的溢出写回都会破坏“combine 不落 HBM”的前提。用伪代码思路描述循环体：对每个 K 步进发起 TMA 预取下一块权重、对当前块做反量化、发起 tcgen05 MMA、在 MMA 完成回调里把结果按路由权重累加进寄存器累加器。举例：当一个 token 被路由到多个专家时，其多个部分和在不同 MMA 上产生，寄存器累加器需要按 token 索引归并，若归并逻辑放在 HBM 侧就退化成未融合形态，因此归并必须在片上完成，代价是寄存器压力随每 token 命中专家数上升。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-11\">十一 · 写回与循环续取：收益边界与退化定位</h3>\n<p>寄存器累加完成后，输出写回全局显存，block 不退出，直接回到循环顶部取下一个 micro-batch。输入是累加器中的最终 token 表示，输出是全局显存中的输出张量，代价是一次写回带宽加一次循环跳转。写回与下一次 TMA 预取可以重叠：写回是全局写，预取是全局读，二者在 HBM 上争带宽但不互相阻塞，这使循环的稳态时延趋近于 $\\max(B_w/\\text{BW}_{\\text{HBM}}, T_{\\text{MMA}}) + T_{\\text{epilogue}}$ 中的后两项之和。</p>\n<p>收益边界由 batch 大小决定：小 batch、带宽受限的量化 MoE decode 是主战场，此时权重加载主导、launch 与 HBM 往返占比高，融合可把 decode 时延降低 30–50%；batch 增大后 GEMM 计算占比上升、launch 开销被摊薄，收益递减。退化定位是这套机制最贵的隐性代价：融合后调试与 profiling 困难，路由分布突变时无法定位是哪个阶段退化——是 TMA 预取没跟上、反量化溢出、还是 TMEM 累加器不够。工程上应把每个阶段的硬件计数器（TMA 事务数、shared memory 溢出次数、MMA 占用率）作为常驻观测点，而不是等端到端时延异常再回溯。举例：某次 decode 时延突然抬升，若 TMA 事务数正常而 shared memory 溢出计数上升，则可判定是反量化缓冲峰值问题而非权重加载问题，这种定位能力必须在融合设计阶段就预留，否则 mega-kernel 会变成一个无法拆解的黑盒。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-12\">十二 · 融合核的边界条件：收益从哪来、又在哪失效</h3>\n<p>把路由、dispatch、反量化、分组 GEMM、combine 压进一个 persistent mega-kernel 之后，解码时延的形态就变了。融合前，多 kernel 流水的时间轴是各阶段串行叠加，每个 kernel 都要把中间缓冲写回 HBM、再由下一个 kernel 读回来，launch 开销与 HBM 往返在小 batch 下占比过半；融合后，时间轴退化为一条以权重加载和 MMA 为双主干的流水线，可近似写成 <span class=\"formula\">$$T_{\\text{fused}} \\approx \\max\\left(\\frac{B_w}{\\text{BW}_{\\text{HBM}}},\\ T_{\\text{MMA}}\\right) + T_{\\text{epilogue}}$$</span> 其中 $B_w$ 是激活专家的量化权重字节数，$\\text{BW}_{\\text{HBM}}$ 是显存带宽，$T_{\\text{MMA}}$ 是矩阵乘时间，$T_{\\text{epilogue}}$ 是寄存器内按路由权重累加与写回的时间。这个式子的关键含义是：融合核的时延不再由阶段数决定，而由“权重搬运”和“矩阵乘”两者中较慢的那个决定，epilogue 只作为一次性的尾部开销出现。也正因如此，收益的大小完全取决于 $B_w/\\text{BW}_{\\text{HBM}}$ 与 $T_{\\text{MMA}}$ 的相对关系——这正是该方案适用边界的数学来源。</p>\n<p>边界的第一条是 batch 规模。小 batch decode 时，每个 token 只激活少量专家，$T_{\\text{MMA}}$ 很小，$B_w/\\text{BW}_{\\text{HBM}}$ 主导整个时延，此时融合消除的 launch 与 HBM 往返开销占比高，收益最明显；随着 batch 增大，GEMM 计算占比上升，$T_{\\text{MMA}}$ 逐渐成为 max 的主项，launch 开销被摊薄，融合带来的相对收益随之下降。换句话说，mega-kernel 是把“固定开销”摊到一条常驻流水线上，而固定开销本来就是小 batch 的病，大 batch 并不生这个病。工程判断上，这套方案应部署在低并发、SLO 对首 token 后逐 token 时延敏感的场景，而不是高吞吐批处理场景。第二条边界是 shared memory 容量：反量化与 token 重排都在 shared memory 内完成，一旦激活专家数与单专家权重块超出片上容量，中间结果就会溢出到 HBM，融合收益被直接抵消，此时 $T_{\\text{fused}}$ 的 max 结构被破坏，退化成带额外往返的多阶段形态。第三条是架构绑定：mega-kernel 依赖 SM100/SM103 的 TMA 与 tcgen05 指令定制，权重为 NVFP4/INT4 格式，跨架构移植成本极高，换一代硬件就要重写指令序列与流水编排。</p>\n<p>失效条件里最隐蔽的一类是路由分布突变。融合核内部各阶段共享同一份片上状态，dispatch 的重排、反量化的缩放因子应用、GEMM 的分组边界、combine 的权重累加全部耦合在一个 kernel 里，一旦某一层专家的路由热度骤变，profiling 只能看到整个 kernel 的时延抬升，无法像多 kernel 流水那样按阶段定位是 dispatch 退化、反量化退化还是 GEMM 分组失衡。调试成本的上升不是线性的：多 kernel 方案里每个阶段有独立的计时器和独立的中间缓冲可 dump，融合后这些观测点全部消失，只剩端到端时间。因此工程上必须预先在 kernel 内埋入轻量计数（例如每个 micro-batch 的专家命中分布、shared memory 占用峰值、TMA 流水深度），用这些计数替代阶段级 profiling。下表把三个步骤的输入、输出与代价并列，便于对照失效点。</p>\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入</th><th>输出</th><th>主要代价</th></tr></thead><tbody><tr><td>取 micro-batch 路由结果</td><td>全局队列中的路由结果</td><td>常驻 SM 上的待处理 token 集合</td><td>队列轮询与常驻占用；避免重复 launch 的收益在此兑现</td></tr><tr><td>TMA 加载 + 反量化 + 重排</td><td>激活专家的 NVFP4/INT4 权重、token 索引</td><td>shared memory 内的反量化权重与重排后激活</td><td>HBM 带宽 $B_w/\\text{BW}_{\\text{HBM}}$；shared memory 容量不足即溢出</td></tr><tr><td>tcgen05 MMA + 寄存器累加</td><td>重排后激活、反量化权重、路由权重</td><td>写回全局显存的输出</td><td>$T_{\\text{MMA}}$ 与 $T_{\\text{epilogue}}$；combine 不落 HBM 是收益来源</td></tr></tbody></table>\n<p>从系统代价看，融合核把“带宽受限”这一约束显式化了：当 $B_w/\\text{BW}_{\\text{HBM}}$ 主导时，GPU 利用率的上限由 HBM 带宽决定，TMA 与 tcgen05 异步流水的意义就是把权重加载与 MMA 重叠，使带宽在被占满的同时计算单元不空转；而一旦 shared memory 溢出，额外往返会把这条流水打断，利用率回落。功耗侧的变化是间接的：常驻 SM 减少了 kernel 切换与重复启动的瞬态开销，但持续占用也让空闲降频的空间变小。与相邻方案相比，多 kernel 流水的可观测性与可移植性更好，融合核则用可观测性换时延；这条交换在小 batch、带宽受限、硬件代际稳定的部署里划算，在跨架构、路由剧烈波动或 shared memory 紧张的部署里不划算。判断是否采用，先看 $B_w/\\text{BW}_{\\text{HBM}}$ 是否显著大于 $T_{\\text{MMA}}$，再看激活专家的权重块能否稳定驻留片上。</p>\n<h3 id=\"alg-monomoe-fused-kernel-sec-13\">十三 · 时延上界的逐项拆解：从 $T_{\\text{decode}}$ 到 $T_{\\text{fused}}$</h3>\n\n<p>多 kernel 流水下的小 batch 量化 MoE decode，其时延可以写成两项竞争加一个不可压缩的尾巴：</p>\n\n<div class=\"formula\">$$T_{\\text{decode}}\\approx\\max\\left(\\frac{\\sum_e |W_e|\\cdot b_w}{\\text{BW}},\\ \\frac{\\text{FLOPs}}{\\text{FLOPs}_{\\text{peak}}}\\right)+\\epsilon_{\\text{launch}},\\quad \\epsilon_{\\text{launch}}\\to 0\\ \\text{(persistent)}$$</div>\n\n<p>第一项是权重字节搬运时间：$\\sum_e |W_e|$ 是本次 micro-batch 路由实际激活的专家权重元素总数，$b_w$ 是每元素比特宽（NVFP4 为 4 bit 加微缩放因子开销，INT4 为 4 bit），除以 HBM 带宽 $\\text{BW}$ 得到纯带宽下界。第二项是 MMA 计算时间，$\\text{FLOPs}$ 只统计被激活专家的 token×hidden 乘加，$\\text{FLOPs}_{\\text{peak}}$ 取 tcgen05 在目标精度下的峰值。$\\epsilon_{\\text{launch}}$ 是 kernel 间启动、同步与中间缓冲 HBM 往返的合并项——在非 persistent 的多 kernel 实现里，它正是占比超过 50% 的那一块。</p>\n\n<p>融合大核做的事情，本质是把 $\\epsilon_{\\text{launch}}$ 从加号后面搬到 max 内部并压向零，同时把中间缓冲的往返从 HBM 挪到片上。于是得到本部分的核心式：</p>\n\n<div class=\"formula\">$$T_{\\text{fused}} \\approx \\max\\left(\\frac{B_w}{\\text{BW}_{\\text{HBM}}},\\ T_{\\text{MMA}}\\right) + T_{\\text{epilogue}}$$</div>\n\n<p>逐项对照：$B_w$ 与上式 $\\sum_e |W_e|\\cdot b_w$ 同义，但含义变窄了——它只计真正被 TMA 搬进 shared memory 的那部分激活专家权重，不再包含 dispatch 中间张量、反量化输出缓冲、combine 输入的字节。$T_{\\text{MMA}}$ 是 tcgen05 异步 MMA 的有效占用时间。$T_{\\text{epilogue}}$ 是寄存器内按路由权重累加与最终写回全局显存的成本，它不再与权重加载竞争带宽，因为写回量级是 token 数×hidden×输出精度，远小于权重字节数。</p>\n\n<p>关键的一步推导在于：为什么 max 里只剩两项而不是三项？因为反量化与 token 重排在 shared memory 内完成，其算力开销被折叠进 $T_{\\text{MMA}}$ 的流水空隙——tcgen05 异步 MMA 在后台跑矩阵乘时，SM 的标量/向量单元正好处理反量化与重排，两者共享同一段墙钟时间。若把反量化单独拆成 kernel，它就要独立占用一次 HBM 读写往返，此时 $T$ 变成三项相加，这正是多 kernel 实现吃亏的根源。工程判断：只要反量化吞吐不低于 MMA 消耗权重的速率，max 就由带宽项或 MMA 项之一主导，融合收益成立；一旦 shared memory 容量不足导致反量化溢出到 HBM，第三项重新出现，融合收益被抵消——这是该设计最脆弱的边界。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-14\">十四 · 带宽项与计算项谁主导：一个可判定的判据</h3>\n\n<p>把两项相除，得到主导性判据：</p>\n\n<div class=\"formula\">$$\\rho=\\frac{B_w/\\text{BW}_{\\text{HBM}}}{T_{\\text{MMA}}}=\\frac{B_w\\cdot \\text{FLOPs}_{\\text{peak}}}{\\text{BW}_{\\text{HBM}}\\cdot \\text{FLOPs}}$$</div>\n\n<p>$\\rho&gt;1$ 时带宽主导，融合大核的收益最大，因为此时唯一的实质成本就是把权重从 HBM 搬到片上，任何多余的 HBM 往返都是纯损失。$\\rho&lt;1$ 时 MMA 主导，融合仍能省掉 launch 与中间缓冲，但相对收益随 batch 增大而摊薄——这正是适用边界里“收益随 batch 增大而下降”的定量表达：batch 增大使 $\\text{FLOPs}$ 线性上升而 $B_w$ 只随激活专家数缓增，$\\rho$ 单调下降。</p>\n\n<p>具体例子：一个 hidden 维度较大、专家粒度较细的 MoE，在 decode 阶段每个 token 只激活少数专家，$\\text{FLOPs}$ 很小而 $B_w$ 相对可观，$\\rho$ 明显大于 1，属于典型带宽受限场景。此时若沿用多 kernel 流水，dispatch 写一次中间缓冲、反量化读一次写一次、分组 GEMM 再读一次，权重与激活被反复搬运，$\\epsilon_{\\text{launch}}$ 叠加在带宽项之上，实测时延远高于 $\\max$ 给出的下界。融合后这些往返消失，$T_{\\text{fused}}$ 逼近 $B_w/\\text{BW}_{\\text{HBM}}$，这正是材料所述“小 batch decode 时延可降低 30–50%”的来源——降的是 $\\epsilon_{\\text{launch}}$ 与中间缓冲，不是 MMA 本身。</p>\n\n<p>代价侧要同时记账：融合后 SM 常驻、shared memory 被权重与重排缓冲长期占用，占用率上升会压低可并发 micro-batch 数；功耗上，TMA 持续满载搬运权重使 HBM 控制器长时间高活动，而 MMA 峰值占用带来瞬时高功耗，两者重叠时对供电与散热提出更高要求。这些不是定性担忧，而是 $\\rho&gt;1$ 场景下必然出现的资源画像。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-15\">十五 · 伪代码：把三步机制落到可实现结构</h3>\n\n<p>下面给出 mega-kernel 的单 SM 视角骨架，刻意保留控制流与同步点，便于直接对照 PTX/CUDA 实现：</p>\n\n<ul>\n<li>常驻循环：<code>while (queue not empty) { mb = dequeue(); }</code>，队列里放的是路由结果（token→专家映射与路由权重），取 micro-batch 不触发新 launch。</li>\n<li>对 mb 内每个激活专家 $e$：发起 TMA 异步拷贝，把 $W_e$ 的 NVFP4/INT4 量化块与微缩放因子搬入 shared memory 的环形缓冲槽；用 mbarrier 记录完成。</li>\n<li>在等待 TMA 的窗口内，对已到达的槽做反量化与 token 重排：按路由把 token 行 gather 成该专家的连续行块，反量化到 MMA 可消费的精度，写回 shared memory 的另一块区域。</li>\n<li>对就绪的行块发起 tcgen05 异步 MMA，累加器驻留 TMEM/寄存器；MMA 完成信号与下一槽的 TMA 完成信号在同一等待集合上汇合，形成流水。</li>\n<li>epilogue：MMA 结果按该 token 的路由权重在寄存器内做加权累加，跨专家结果在寄存器/TMEM 内合并，combine 不写 HBM。</li>\n<li>mb 全部专家处理完后，把该 micro-batch 的输出一次性写回全局显存，回到常驻循环取下一个 mb。</li>\n</ul>\n\n<p>伪代码层面的三个不变量决定了正确性：其一，TMA 槽的复用必须由 mbarrier 的到达计数严格保护，否则反量化会读到半写权重；其二，token 重排的索引必须在反量化前固定，避免 MMA 消费到错位行；其三，寄存器累加的跨专家合并要求同一 token 的所有激活专家结果在同一 SM 上收齐——这约束了 dispatch 的分组策略，若某 token 的专家被分到不同 SM，combine 就必须回到 HBM，融合失效。这条约束是本设计对上游路由的直接要求，也是与专家并行 All-to-All 调度的耦合点。</p>\n\n<p>系统代价在此显形：常驻 SM 意味着该 kernel 独占计算资源，无法与其他 kernel 时间片共享，调度器必须为它预留 SM 配额；shared memory 槽数与 TMEM 容量共同决定流水深度，槽太少则 TMA 与 MMA 无法重叠，$\\max$ 退化为相加；槽太多则占用率下降、并发 micro-batch 减少。调试困难也源于此：路由分布突变时，退化可能表现为 TMA 槽饥饿、反量化吞吐不足或 TMEM 压力，三者都藏在同一个 kernel 内，profiling 只能靠自埋计数器区分阶段。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-16\">十六 · 流水重叠的定量条件：TMA 与 tcgen05 的速率匹配</h3>\n\n<p>融合能压掉 $\\epsilon_{\\text{launch}}$ 的前提是权重加载与 MMA 真正重叠，这要求单位时间内 TMA 搬入的权重字节不少于 MMA 消费的字节：</p>\n\n<div class=\"formula\">$$\\frac{B_w}{T_{\\text{MMA}}}\\ \\le\\ \\text{BW}_{\\text{TMA}\\to\\text{SMEM}}$$</div>\n\n<p>左侧是 MMA 消耗权重的等效速率，右侧是 TMA 到 shared memory 的有效带宽（受槽数、mbarrier 周转、HBM 行冲突影响，通常低于裸 HBM 带宽）。当该不等式成立，$T_{\\text{fused}}$ 由 $\\max$ 中的较大项决定，流水无气泡；当它被违反，MMA 会周期性等待权重，实际时延退化为两项相加，融合只省了 launch 却省不了搬运。</p>\n\n<p>具体例子：权重为 NVFP4 时 $b_w$ 很小，同样的 $|W_e|$ 对应字节数只有 FP16 的四分之一左右，左侧速率随之下降，不等式更容易满足——这是量化与融合大核天然搭配的原因：量化先把 $B_w$ 压下来，融合再把往返开销压下去，两者作用在不同项上，不重复。反过来，若激活量化细节未定、反量化需要在 shared memory 内做较重的缩放计算，反量化吞吐可能成为新的瓶颈，此时即便不等式成立，$T_{\\text{epilogue}}$ 也会被反量化拖长，需要在槽设计上为反量化留出独立流水级。</p>\n\n<p>代价记账：提高流水深度（增加槽数）能改善不等式右侧，但 shared memory 占用上升会压缩可并发的 micro-batch 数与 occupancy，进而影响隐藏延迟的能力；TMEM 被 MMA 累加器长期占用同样限制并发。工程上这是一个二维权衡：槽数与 TMEM 分配要按 $\\rho$ 与不等式共同定，带宽主导场景优先加深 TMA 流水，MMA 主导场景优先保证累加器容量与 epilogue 吞吐。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-17\">十七 · 失败模式的公式化定位与移植成本</h3>\n\n<p>三类失败模式都能在公式里找到对应项。第一，shared memory 容量不足：反量化与 token 重排溢出到 HBM，等价于在 $T_{\\text{fused}}$ 的 max 之外重新引入一个 HBM 往返项，$T_{\\text{epilogue}}$ 被放大且与 $B_w/\\text{BW}_{\\text{HBM}}$ 串行，融合收益被抵消——判据是 shared memory 需求（权重槽 + 重排缓冲 + 反量化临时区）超过单 SM 可用容量，此时应缩小槽数或改用更激进的权重驻留策略，而不是硬扛。</p>\n\n<p>第二，路由分布突变导致退化不可定位：$\\rho$ 与不等式都随激活专家集合变化，突变时 $B_w$ 与 $\\text{FLOPs}$ 同时改变，可能从带宽主导瞬间切到 MMA 主导，或使 TMA 槽饥饿。由于所有阶段在同一 kernel 内，外部 profiler 只能看到整体时延上升，无法区分是 TMA、反量化还是 MMA 退化。可实现的缓解是在 kernel 内埋轻量计数器（每阶段等待周期、槽空转次数），按 micro-batch 聚合后异步写回，代价是少量寄存器和一次额外写回，换来可观测性。</p>\n\n<p>第三，跨架构移植成本极高：mega-kernel 绑定 SM100/SM103 的 TMA 与 tcgen05 指令语义，mbarrier 协议、TMEM 分配、MMA 描述符格式都与架构强相关，换架构等于重写而非调参。这条代价无法用公式消除，只能作为选型判断：若部署目标锁定 Blackwell 且负载以带宽受限的小 batch decode 为主，融合大核的收益足以覆盖实现成本；若需跨多代架构统一推理栈，则应把融合限制在可替换的后端模块内，保留多 kernel 路径作为回退。</p>\n\n<p>最后落到一个具体机制判断：epilogue 的寄存器内累加是融合成立的必要条件而非优化项——一旦跨 SM 的 token 专家结果无法在寄存器/TMEM 内收齐，combine 就必须落 HBM，此时 $T_{\\text{epilogue}}$ 与 $B_w/\\text{BW}_{\\text{HBM}}$ 串行，max 结构被破坏，整个推导失效。因此路由分组策略与 SM 分配必须以保证“单 token 激活专家同 SM 收齐”为硬约束，这比任何微架构调优都更早决定融合大核能否兑现其 30–50% 的时延收益。</p>\n\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-18\">十八 · 融合大核的失效边界与系统代价</h3>\n<p>把时延公式拆开看，融合收益的成立条件其实很窄。$$T_{\\text{fused}} \\approx \\max\\left(\\frac{B_w}{\\text{BW}_{\\text{HBM}}},\\ T_{\\text{MMA}}\\right) + T_{\\text{epilogue}}$$ 中 $B_w$ 是激活专家的量化权重字节数，$\\text{BW}_{\\text{HBM}}$ 是显存带宽，$T_{\\text{MMA}}$ 是矩阵乘时间，$T_{\\text{epilogue}}$ 是寄存器内按路由权重累加与写回时间。关键一步在于：多 kernel 版本里 $\\epsilon_{\\text{launch}}$ 与中间缓冲的 HBM 往返是加在 max 之外的独立项，而融合后它们被吸收进流水，只剩 $T_{\\text{epilogue}}$ 无法隐藏。因此收益大小取决于 $\\frac{B_w}{\\text{BW}}$ 与 $T_{\\text{MMA}}$ 谁主导——带宽受限时权重加载是瓶颈，TMA 与 tcgen05 的重叠能把这段填满；一旦 batch 增大使 $T_{\\text{MMA}}$ 反超，max 由计算项决定，融合省下的 launch 与往返被摊薄，收益随 batch 单调下降。</p>\n<p>失效条件集中在三处。其一，shared memory 容量不足时，反量化与 token 重排的工作集溢出到 HBM，中间结果重新落盘，融合收益被直接抵消，这是最隐蔽的退化路径，因为 profiler 上表现为带宽上升而非逻辑错误。其二，路由分布突变（某专家 token 数骤增）会让单个 micro-batch 的权重加载量超出流水预算，TMA 预取深度不够，MMA 空转等待，而此时 mega-kernel 内部各阶段耦合，无法定位是 dispatch 重排、反量化还是 GEMM 退化。其三，代码绑定 SM100/SM103 的 TMA 与 tcgen05 指令并需手写 PTX/CUDA，跨架构移植成本极高，等于把可移植性换成了时延。</p>\n<table class=\"mini\"><thead><tr><th>场景</th><th>主导项</th><th>融合收益</th><th>主要风险</th></tr></thead><tbody><tr><td>小 batch、带宽受限</td><td>$B_w/\\text{BW}$</td><td>显著，launch 与往返占比高</td><td>shared memory 溢出</td></tr><tr><td>batch 增大</td><td>$T_{\\text{MMA}}$</td><td>被摊薄</td><td>收益递减</td></tr><tr><td>路由突变</td><td>流水失衡</td><td>不确定</td><td>退化阶段不可定位</td></tr></tbody></table>\n<p>工程判断上，这套方案应作为小 batch decode 的专用路径而非通用解码核：部署时按 micro-batch 逐个从全局队列取路由结果，把 shared memory 预算当作硬约束反推可容纳的专家权重分片与 token 重排缓冲，并在路由分布监控上留出回退到多 kernel 流水的开关。与 paper-monomoe-an-efficient-fused-mega-kern-2026、paper-sonicmoe-accelerating-moe-with-io-an-2025 所代表的融合路线相比，它的代价不在算力而在可维护性：调试与 profiling 困难意味着任何一次路由分布漂移都可能让团队失去对退化来源的定位能力。</p>\n<h3 id=\"alg-monomoe-fused-kernel-sec-19\">十九 · 请求形态：小 batch 才是主场</h3>\n<p>融合大核的负载配方第一条是请求形态。它面向的是<strong>小 batch decode</strong>：每个请求每步只产生一个 token，路由结果稀疏且专家命中高度分散，单次 GEMM 的 M 维很小。此时若沿用多 kernel 流水，路由、dispatch、反量化、分组 GEMM、combine 各自都要把中间缓冲写回 HBM 再读出来，而每个 kernel 的固定 launch 开销在小 batch 下无法被计算量摊薄。材料给出的判断是：小 batch 下 kernel launch 与 HBM 往返开销占比超过 50%。这就是融合大核存在的理由——它把整条链路压成一个常驻 SM 的 persistent kernel，micro-batch 从全局队列逐个取，中间结果留在 shared memory 与寄存器里，launch 次数从每步多次降为一次常驻。</p>\n<p>反过来看，什么形态不适合。大 batch 预填、长上下文一次性灌入、或批大小大到 GEMM 计算占比压过权重加载时，融合的边际收益迅速衰减。原因是融合核的时延近似为</p>\n<div class=\"formula\">$$T_{\\text{fused}} \\approx \\max\\left(\\frac{B_w}{\\text{BW}_{\\text{HBM}}},\\ T_{\\text{MMA}}\\right) + T_{\\text{epilogue}}$$</div>\n<p>其中 $B_w$ 是权重字节数、$\\text{BW}_{\\text{HBM}}$ 是显存带宽、$T_{\\text{MMA}}$ 是矩阵乘时间、$T_{\\text{epilogue}}$ 是寄存器累加与写回时间。小 batch 时 $\\text{BW}_{\\text{HBM}}$ 项主导，融合省下的 HBM 往返直接兑现为时延；大 batch 时 $T_{\\text{MMA}}$ 项主导，省不省 launch 已经无关紧要。所以配方上要明确：这是 decode 侧的带宽受限优化，不是预填侧的算力受限优化。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-20\">二十 · 长度分布：短请求密集才喂得饱队列</h3>\n<p>长度分布决定全局队列里 micro-batch 的供给节奏。融合核常驻 SM 后靠队列取活，队列一旦断供，SM 就空转，而空转的代价不是零——persistent kernel 占着 SM 不放，别的 kernel 也进不来。因此负载配方要求请求长度分布相对集中、短请求占比高：短输出意味着 decode 步数少、每步都能快速产出新的路由结果，队列周转快；长尾请求则会让某几个 micro-batch 在专家上停留过久，拖住整条流水。</p>\n<p>工程上的判断是看<strong>队列深度与单步时延的比值</strong>。设单 micro-batch 的融合核时延为 $T_{\\text{fused}}$，若平均队列深度 $D$ 满足 $D \\cdot T_{\\text{fused}}$ 覆盖一次权重加载的 TMA 流水窗口，则 TMA 与 tcgen05 异步 MMA 的重叠才能真正生效；否则权重加载的延迟会裸露在关键路径上。长度分布越偏长尾，越容易出现某个 micro-batch 只命中一两个专家、却仍要等整批权重搬运的尴尬局面，此时融合核的带宽利用率反而低于多 kernel 流水——因为多 kernel 至少能把不同阶段的工作交错排布。</p>\n<p>具体例子：一个对话服务里 90% 请求输出在几十个 token 量级、10% 是长文续写。前者的 decode 步密集、路由结果源源不断，融合核能吃满；后者每步都要重新加载一批专家权重，且这些请求的 micro-batch 往往凑不满一个 TMA 窗口，融合核的 $\\max$ 项退化为纯带宽等待。配方上应把长尾请求分流到另一条执行路径，而不是硬塞进同一个 persistent kernel。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-21\">二十一 · 并发与批大小：micro-batch 是调度单位，不是越大越好</h3>\n<p>并发数决定全局队列里同时有多少路由结果待处理，批大小决定每个 micro-batch 塞多少 token。融合核的调度单位是 micro-batch，其大小需要与 shared memory 容量、TMA 传输粒度、tcgen05 MMA 的 tile 形状三者对齐。批太小，MMA 的 M 维填不满 tile，算力浪费；批太大，shared memory 里反量化与 token 重排的缓冲吃紧，一旦溢出到 HBM，融合收益直接被抵消——这是材料明确列出的失败模式之一。</p>\n<p>并发与批大小的配比还影响专家命中分布。并发高时，同一 micro-batch 内多个 token 命中同一专家的概率上升，分组 GEMM 的有效 M 维变大，$T_{\\text{MMA}}$ 项占比提高，融合核从带宽受限滑向算力受限，收益递减。并发低时，专家命中极度分散，每个专家只分到零星 token，权重加载的字节数不变而有效计算量极小，$\\frac{B_w}{\\text{BW}_{\\text{HBM}}}$ 项完全主导，此时融合核的时延几乎等于把所有命中专家的权重复制一遍的时间。</p>\n<p>因此配方上要设一个<strong>并发下限</strong>：低于该下限，路由分散度太高，融合核不如退回多 kernel 流水让各阶段交错；高于某个上限，则应转向更大的批或预填解码分离部署，把 decode 侧留给融合核、预填侧交给别的路径。材料未给出具体批大小与 SLO 数值，工程上应以实测的队列断供率与 shared memory 溢出率为两个判据来定标。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-22\">二十二 · 负载不对时的退化路径</h3>\n<p>负载偏离配方时，融合核不会温和降级，而是出现几种特征性退化。第一种是<strong>队列断供空转</strong>：并发不足导致全局队列取不到 micro-batch，persistent kernel 占着 SM 却无活可干，此时 GPU 利用率掉到低位，而多 kernel 流水至少能把空转的 SM 让给别的 kernel。第二种是<strong>shared memory 溢出</strong>：批偏大或专家命中过于集中，反量化与 token 重排的中间缓冲超出 shared memory 容量，被迫落回 HBM，融合省下的往返又被加回去，净收益归零甚至为负。</p>\n<p>第三种是<strong>路由分布突变导致的定位困难</strong>。材料指出融合后调试与 profiling 困难，路由分布突变时难以定位是哪个阶段退化。多 kernel 流水里每个阶段是独立 kernel，profiler 能直接给出各阶段的耗时；融合核里 dispatch、反量化、GEMM、combine 全在一个 kernel 内，退化只能从整体时延反推，无法直接归因。这对负载配方的含义是：必须在上线前把路由分布的稳定性纳入容量规划，突变场景（如新业务流量涌入、提示词模板切换）要有独立的观测手段，否则退化发生时只能盲调。</p>\n<p>第四种是<strong>跨架构移植失效</strong>。融合核绑定 SM100/SM103 的 TMA 与 tcgen05 指令，负载配方里隐含了“部署在 Blackwell 上”这一前提；换到别的架构，手写 PTX/CUDA 的路径全部作废，移植成本极高。配方文档应把硬件代际作为一等约束写进去，而不是当作部署细节。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-23\">二十三 · 配方与容量规划的接口</h3>\n<p>把负载配方落到容量规划上，需要三个观测量：队列深度、shared memory 占用峰值、单 micro-batch 时延。队列深度低于阈值即触发扩容或分流；shared memory 占用逼近容量上限即触发批大小下调；单 micro-batch 时延的方差变大则提示路由分布正在漂移。这三个量都不需要拆开融合核内部，正好绕开了 profiling 困难的短板。</p>\n<p>配方还要与相邻机制划清边界。容量因子路由与令牌丢弃、专家选择路由决定的是路由结果的形状与分散度，融合核只是消费这些结果；无丢弃块稀疏分组 GEMM 处理的是分组 GEMM 本身的稀疏结构，融合核把它连同 dispatch、反量化、combine 一起吞进 shared memory。负载不对时，先怀疑的是上游路由产出的形状是否适配融合核的 tile 与缓冲，而不是融合核本身写错了。具体例子：若上游路由把容量因子调得过紧导致大量令牌被丢弃，micro-batch 的有效 token 数骤降，融合核的 M 维填不满，时延不降反升——这不是融合核的退化，是配方与上游路由参数不匹配。</p>\n<p>最后一个工程判断落在 micro-batch 的取数节奏上。融合核从全局队列逐个取，取数节奏应与 TMA 流水窗口对齐：当前 micro-batch 的 MMA 还在跑时，下一个 micro-batch 的路由结果就应已在队列里待命，使权重加载与 MMA 的重叠不出现气泡。队列里待命的 micro-batch 数量少于流水级数，重叠就断；多于流水级数，队列本身成为延迟来源。这个数量由 $T_{\\text{fused}}$ 与 TMA 传输时间之比决定，是负载配方里最需要实测标定的一个参数。</p>\n\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-24\">二十四 · 负载配方：小批解码的甜区与越界后的反噬</h3>\n<p>这一节只谈边界。mega-kernel 的收益不是无条件成立的，它把 dispatch、反量化、分组 GEMM、combine 全部压进一个常驻 SM 的持久核，本质上是用“空间换时间”——用 shared memory 和寄存器替掉 HBM 中间缓冲，用常驻替掉重复 launch。这套交易只有在<strong>单次解码迭代的权重字节数足以主导时延</strong>时才划算。融合后的时延近似为 <div class=\"formula\">$$T_{\\text{fused}} \\approx \\max\\left(\\frac{B_w}{\\text{BW}_{\\text{HBM}}},\\ T_{\\text{MMA}}\\right) + T_{\\text{epilogue}}$$</div> 其中 $B_w$ 是本次 micro-batch 激活专家的量化权重字节数，$T_{\\text{MMA}}$ 是 tcgen05 矩阵乘时间，$T_{\\text{epilogue}}$ 是寄存器内按路由权重累加与写回的时间。对照多 kernel 版本的 <div class=\"formula\">$$T_{\\text{decode}}\\approx\\max\\left(\\frac{\\sum_e |W_e|\\cdot b_w}{\\text{BW}},\\ \\frac{\\text{FLOPs}}{\\text{FLOPs}_{\\text{peak}}}\\right)+\\epsilon_{\\text{launch}}$$</div> 差别就在 $\\epsilon_{\\text{launch}}$ 与 kernel 间 HBM 往返：小 batch 下这两项占比超过 50%，融合把它们压到接近零，所以时延能降 30–50%；batch 一大，$\\max$ 里的第二项（计算）抬头，$\\epsilon_{\\text{launch}}$ 被摊薄，融合的边际收益迅速衰减。</p>\n<p>由此得到负载配方的三条硬约束。其一，<strong>请求形态必须是短输出、低并发的在线解码</strong>：micro-batch 从全局队列逐个取，队列里攒的是路由结果而非原始 token，适合 chat、代码补全这类逐 token 推进、单步计算量小的形态；长上下文预填或大批离线打分不属于它的目标区间。其二，<strong>长度分布要偏窄</strong>：若同一批里混着极短与极长序列，micro-batch 内各 token 的路由专家集合差异过大，shared memory 里为反量化与 token 重排预留的缓冲要按最坏情况分配，容量一旦不够就会溢出到 HBM，融合收益被直接抵消——这是最隐蔽的失效条件。其三，<strong>并发与批大小要压在权重带宽主导的区间</strong>：材料未给出具体批大小与 SLO 数值，工程上应以“单步 $B_w/\\text{BW}_{\\text{HBM}}$ 仍大于 $T_{\\text{MMA}}$”为判据反推上限，超过这条线就该退回多 kernel 流水或改用更大的 tile 切分。</p>\n<p>负载不对时的失效是分层的，且因为融合而更难定位。路由分布突变（例如流量从通用问答切到某垂直领域，专家命中集中到少数几个）会让某个 expert 的权重加载成为串行瓶颈，TMA 流水被打断，但 profiling 只能看到整个 mega-kernel 变慢，无法区分是 dispatch 退化、反量化溢出还是 MMA 空转——融合把阶段边界抹掉了，这既是性能来源也是可观测性的代价。跨架构则是另一道墙：mega-kernel 需手写 PTX/CUDA 并绑定 SM100/SM103 的 TMA 与 tcgen05 指令，移植到别的架构成本极高，等于把负载配方和硬件代际锁死。最后是功耗与占用：常驻 SM 的持久核让 GPU 利用率在带宽受限场景接近峰值，但也意味着它不轻易让出 SM，与同卡上的其他服务争抢时调度弹性变差。</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>融合收益</th><th>主要风险</th></tr></thead><tbody><tr><td>小 batch、短输出、带宽受限</td><td>高（launch 与 HBM 往返占比 &gt;50% 被消除）</td><td>shared memory 容量与最坏情况缓冲</td></tr><tr><td>中等 batch、长度分布窄</td><td>中（计算项抬头，收益衰减）</td><td>需按 $B_w/\\text{BW}$ 与 $T_{\\text{MMA}}$ 判据设上限</td></tr><tr><td>大 batch 或长预填</td><td>低甚至负</td><td>应退回多 kernel 流水</td></tr><tr><td>路由分布突变</td><td>不确定</td><td>无法定位退化阶段，调试困难</td></tr></tbody></table>\n<p>工程判断落在一条可操作的准入线上：先把目标负载的 $B_w/\\text{BW}_{\\text{HBM}}$ 与 $T_{\\text{MMA}}$ 实测出来，只有当权重带宽项稳定压过计算项、且 micro-batch 内专家集合的方差可控时，才值得为这套 mega-kernel 付出手写 PTX 与绑定 SM100/SM103 的移植代价；否则融合带来的 30–50% 时延收益会被溢出与不可观测性吃掉。</p>\n<h3 id=\"alg-monomoe-fused-kernel-sec-25\">二十五 · 硬件档位与 SM 常驻预算</h3>\n<p>部署这套融合大核的第一步不是写 kernel，而是先确定硬件档位能给出多少常驻资源。mega-kernel 的设计前提是每个 SM 上有一个长期存活的 CTA，它自己从全局队列拉 micro-batch 的路由结果，因此 CTA 数量必须与目标 GPU 的 SM 数整除对齐：B200 单 die 的 SM 数与 GB200 NVL72 中单颗 GPU 的 SM 数不同，SM100 与 SM103 在 tcgen05 的 TMEM 分配粒度上也有差异，配置时要把“每 SM 一个常驻 CTA”写成显式约束而不是让 grid 维度自由浮动，否则调度器会把 CTA 摊到多个 SM 上，persistent 语义立刻失效。</p>\n<p>常驻预算的核心是 shared memory 与 TMEM 的静态划分。每个 CTA 需要同时容纳：当前 micro-batch 激活专家的量化权重 tile、反量化后的激活值暂存区、token 重排索引、以及 tcgen05 MMA 的累加器描述符。权重 tile 的大小由 NVFP4/INT4 的块尺度结构决定，反量化缓冲区则由 tile 形状与元素位宽决定。可用约束写成：</p>\n<div class=\"formula\">$$S_{\\text{smem}} \\ge S_{W\\text{-tile}} + S_{\\text{deq}} + S_{\\text{idx}} + S_{\\text{barrier}},\\qquad \\text{TMEM}_{\\text{alloc}} \\le \\text{TMEM}_{\\text{per-SM}}$$</div>\n<p>一旦 $S_{\\text{smem}}$ 不够，反量化与 token 重排就会溢出到 HBM，融合收益被抵消——这是材料明确列出的失败模式。工程判断是：先在目标档位上用最小 tile 跑通，再按 shared memory 余量向上调 tile，而不是先按理论最大 tile 设计再向下裁剪。代价方面，常驻 CTA 占满 SM 意味着没有空闲 SM 处理其他 kernel，因此这套部署适合 decode 专用实例，不适合与预填或其他服务混跑同一组 SM。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-26\">二十六 · 并行拓扑：EP 组内融合、组间走网络</h3>\n<p>mega-kernel 融合的是单个专家并行组内部的 dispatch、反量化、分组 GEMM 与 combine，跨 EP rank 的 all-to-all 仍然发生在 kernel 之外。因此拓扑配置要把两件事分开：组内拓扑决定融合核的 tile 与队列深度，组间拓扑决定 all-to-all 的带宽预算。组内应让同一 EP rank 的专家权重在 HBM 上连续排布，使 TMA 能以大步长整块搬运；组间则依赖 NVLink 5 与 NCCL/NIXL 完成 token 交换，融合核只消费已经落到本 rank 的路由结果。</p>\n<p>一个可复现的配置思路是：把 EP 度数设为与单机 NVLink 域内 GPU 数一致，使组内 all-to-all 不出机；跨机扩展交给分离式部署或分层 all-to-all。全局队列的深度要与 EP 度数匹配——队列太浅，常驻 CTA 会空转等路由结果；队列太深，micro-batch 在队列里排队引入额外时延。队列条目应携带目标 EP rank 与专家 id，让 CTA 在取任务时就能预取对应权重 tile 的 TMA 描述符。</p>\n<p>代价落在带宽上：融合核内部权重加载走 HBM，跨 rank 的激活搬运走 NVLink。当 EP 度数增大，单 rank 分到的专家变少、权重总量下降，HBM 侧压力减轻，但 all-to-all 的激活字节数随 token 数线性增长。因此在带宽受限的小 batch 场景，增大 EP 度数对融合核是有利的；而在 token 密集时，all-to-all 会成为新的瓶颈，此时应回到更小的 EP 度数并让融合核处理更多专家。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-27\">二十七 · 量化方案：权重 NVFP4/INT4，激活侧留出接口</h3>\n<p>材料给出的部署配方只明确了权重为 NVFP4/INT4 量化格式，激活量化细节未给出。这意味着配置时必须把反量化阶段写成可替换的模板：权重侧按块尺度解包，激活侧无论是保持高精度还是走动态量化，都在 shared memory 内的同一段反量化代码路径上分支。把激活量化策略做成编译期开关而不是运行期分支，可以避免在常驻 CTA 的热路径上引入谓词开销。</p>\n<p>权重格式的选择直接影响 TMA 搬运效率。NVFP4 的块尺度元数据与权重主体交错存放时，TMA 需要一次搬两块区域；若把尺度单独打包成连续数组，则主搬运与尺度搬运可以拆成两条 TMA 流水，与 tcgen05 MMA 重叠得更充分。INT4 没有块尺度，搬运更简单，但反量化时的缩放因子要来自激活侧，配置上要把这条依赖写进 tile 描述符。</p>\n<p>代价体现在两个方向：位宽越低，$B_w$ 越小，融合核的权重加载时间按 $\\frac{B_w}{\\text{BW}_{\\text{HBM}}}$ 下降，带宽受限场景直接受益；但反量化在 shared memory 内做的算术量上升，若反量化吞吐跟不上 MMA，$T_{\\text{MMA}}$ 之外的 epilogue 就会被拉长。工程判断是：先用 NVFP4 跑通端到端，再用 INT4 做对照，观察 $T_{\\text{fused}}$ 中哪一项占主导，据此决定是否值得为更低位宽付出反量化复杂度。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-28\">二十八 · KV 策略：与专家权重共享显存时的配额</h3>\n<p>分页 KV 与专家权重共存显存的问题在其他片段已展开，这里只讲部署配额。融合核常驻 SM 后，HBM 上同时存在三块占用：专家量化权重、分页 KV 池、以及全局队列与输出缓冲。权重是静态的，KV 池随并发增长，队列缓冲很小但必须 pinned。配置时应先按 EP 度数算出单 rank 的权重字节数，把剩余显存按目标并发与每 token KV 字节数反推 KV 池上限，再把队列缓冲作为固定扣除项。</p>\n<div class=\"formula\">$$M_{\\text{KV}} \\le M_{\\text{HBM}} - \\sum_{e\\in\\text{rank}} |W_e|\\cdot b_w - M_{\\text{queue}} - M_{\\text{out}}$$</div>\n<p>KV 策略与融合核的交互点在 micro-batch 的取数节奏：每个 micro-batch 的 token 数决定了本次要读多少 KV，若 KV 池被权重挤到很小，micro-batch 只能做得很浅，常驻 CTA 频繁在队列上空转。反过来，若为了拉长 micro-batch 而压缩权重精度，反量化开销又会上升。可复现的做法是把 KV 池配额写成并发上限的函数，在压测中观察 $T_{\\text{fused}}$ 随并发的变化曲线，找到权重精度与 KV 容量之间的拐点。</p>\n<p>代价是显存带宽的竞争：融合核加载权重走 HBM，KV 读取也走 HBM，两者在同一时间段争抢带宽。若 micro-batch 内先做权重 TMA 再做 KV 读取，可以把 KV 读取排到 MMA 流水之后，用 tcgen05 异步特性掩盖一部分；但这也要求 KV 页表查询在 CTA 内完成而不是另起 kernel，否则又多一次 launch。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-29\">二十九 · 调度参数与可复现配置清单</h3>\n<p>调度参数围绕全局队列展开：micro-batch 大小、队列深度、CTA 与队列的绑定关系、以及输出写回的批粒度。micro-batch 从全局队列逐个取，材料未给出具体批大小与 SLO 数值，因此配置思路是把 micro-batch 大小作为可调参数，从 1 开始向上扫，记录每个档位下 $T_{\\text{fused}}$ 的分解——权重加载时间、MMA 时间、epilogue 时间。当权重加载时间开始被 MMA 时间追上，说明 micro-batch 已大到让计算占比上升，融合收益随 batch 增大而下降的边界就在这里。</p>\n<p>队列深度按 EP 度数的整数倍设置，保证每个常驻 CTA 至少有一个待处理条目在途。输出写回采用固定大小的环形缓冲，写满即触发一次批量落盘，避免每个 micro-batch 都做一次小写入。CTA 与队列的绑定建议用静态映射：CTA id 对队列分片取模，使同一 CTA 反复消费同一分片，路由结果的局部性更好，权重 tile 的 TMA 描述符也能被复用。</p>\n<table class=\"mini\"><thead><tr><th>配置项</th><th>取值思路</th><th>约束来源</th></tr></thead><tbody>\n<tr><td>常驻 CTA 数</td><td>等于目标 GPU 的 SM 数</td><td>persistent 语义要求</td></tr>\n<tr><td>EP 度数</td><td>与单机 NVLink 域内 GPU 数一致</td><td>组内 all-to-all 不出机</td></tr>\n<tr><td>权重格式</td><td>NVFP4 优先，INT4 对照</td><td>材料给定权重格式</td></tr>\n<tr><td>激活量化</td><td>编译期开关，模板化反量化</td><td>材料未给出激活细节</td></tr>\n<tr><td>micro-batch</td><td>从 1 向上扫至权重加载被 MMA 追上</td><td>收益随 batch 增大而下降</td></tr>\n<tr><td>队列深度</td><td>EP 度数的整数倍</td><td>避免 CTA 空转</td></tr>\n<tr><td>KV 池</td><td>剩余显存反推并发上限</td><td>与权重共享 HBM</td></tr>\n</tbody></table>\n<p>这套清单的可复现性依赖两点：一是把每个参数与它约束的失败模式一一对应，shared memory 不足对应 tile 上限，队列太浅对应 CTA 空转，KV 配额不足对应 micro-batch 变浅；二是把 profiling 埋点在融合核内部按阶段打时间戳，因为融合后调试与 profiling 困难，路由分布突变时无法定位退化阶段，只有阶段级计时才能区分是权重加载、反量化还是 epilogue 出了问题。跨架构移植成本极高这一点也要写进配置文档：SM100 与 SM103 的 TMA 与 tcgen05 指令定制部分不可直接复用，换档位等于重做一遍常驻预算与 tile 划分。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-30\">三十 · 融合大核的适用边界：什么配置下它真的省时</h3>\n<p>这套部署配方的核心判断只有一条：<strong>mega-kernel 的收益来自“把中间缓冲留在片上”，因此它的有效区间由 shared memory 容量与 batch 规模共同界定。</strong>配方本身可以写成四个档位的组合——硬件档位锁 SM100/SM103（B200/B300、GB200/GB300 NVL72），并行拓扑取专家并行加张量并行、EP 组内走 NVLink 5 域、跨节点走 NIXL 搬运 KV 与路由元数据，量化方案固定权重为 NVFP4/INT4、激活量化细节按框架默认走，KV 策略沿用分页加前缀复用、不在此节展开，调度参数则把 micro-batch 设为“全局队列逐个取”的最小粒度。真正需要工程判断的是：这套组合在什么条件下退化。融合后时延近似为</p>\n<div class=\"formula\">$$T_{\\text{fused}} \\approx \\max\\left(\\frac{B_w}{\\text{BW}_{\\text{HBM}}},\\ T_{\\text{MMA}}\\right) + T_{\\text{epilogue}}$$</div>\n<p>其中 $B_w$ 是本次 micro-batch 激活专家的量化权重字节数。小 batch 下 $B_w/\\text{BW}_{\\text{HBM}}$ 主导，融合把原本分散在 dispatch、反量化、分组 GEMM、combine 四个 kernel 之间的 HBM 往返全部消掉，收益最明显；batch 增大后 $T_{\\text{MMA}}$ 抬升、launch 开销被摊薄，收益单调下降。这就是边界的第一条：<strong>它不是大 batch 吞吐方案，而是小 batch 时延方案。</strong>把它塞进高并发在线服务的主路径，等于用复杂度换一个已经被摊薄的常数项。</p>\n<p>第二条边界是 shared memory 容量。反量化与 token 重排在片上完成，前提是激活专家的权重切片加中间激活能同时驻留；一旦超出，编译器或手写代码会把部分缓冲溢出到 HBM，此时 $T_{\\text{fused}}$ 里的 $\\max$ 项不再成立，实际时延退化为“融合 kernel + 额外 HBM 往返”，不但抵消收益，还可能比多 kernel 流水更慢，因为溢出路径没有经过精心调优的流水重叠。工程上必须按最坏路由分布（单 token 命中专家数最多、专家权重切片最大）核算片上占用，并留出 TMA 双缓冲的余量；核算不通过就应退回多 kernel 方案，而不是靠调小 micro-batch 硬撑——micro-batch 太小会让 MMA 流水填不满，$T_{\\text{MMA}}$ 之外的固定开销重新占主导。</p>\n<p>第三条边界是架构绑定与可观测性。mega-kernel 需手写 PTX/CUDA 并针对 SM100/SM103 的 TMA 与 tcgen05 指令定制，跨架构移植成本极高，这意味着配方一旦落地就锁死在 Blackwell 这一代，不能作为跨代通用路径规划容量。更麻烦的是失效定位：融合后调试与 profiling 困难，路由分布突变时无法定位退化发生在反量化、token 重排还是 MMA 累加阶段——单 kernel 内部没有天然的阶段边界，profiler 只能看到一整块时间。可复现的配置思路因此要附带一条诊断约束：在 mega-kernel 内埋入按 micro-batch 的阶段计时计数器（反量化起止、MMA 起止、epilogue 起止），以极低开销写回全局缓冲，使路由漂移时能判断是哪个子阶段变慢；没有这套埋点，配方不可运维。下表给出配方各档位的失效条件与系统代价对照。</p>\n<table class=\"mini\"><thead><tr><th>配方档位</th><th>典型取值</th><th>失效条件</th><th>系统代价</th></tr></thead><tbody><tr><td>硬件档位</td><td>SM100/SM103，单机 NVLink 5 域</td><td>跨代部署</td><td>移植需重写 PTX，容量规划锁代</td></tr><tr><td>并行拓扑</td><td>EP + TP，EP 组内 NVLink 5</td><td>EP 组跨节点、路由元数据搬运增多</td><td>NIXL 传输占带宽，dispatch 队列延迟上升</td></tr><tr><td>量化方案</td><td>权重 NVFP4/INT4</td><td>激活量化精度不足致路由漂移</td><td>反量化在片上做，占 shared memory</td></tr><tr><td>调度参数</td><td>micro-batch 逐个取</td><td>batch 增大、launch 摊薄</td><td>收益下降，复杂度不变</td></tr></tbody></table>\n<p>把三条边界合起来看，这个配方的工程判断是：<strong>它适合“低 QPS、严时延、专家路由相对稳定”的 decode 场景</strong>，例如交互式单流或小并发推理，此时 $\\epsilon_{\\text{launch}}\\to 0$ 的 persistent 结构把固定开销压到最低，TMA 与 tcgen05 异步流水让带宽受限下的 GPU 利用率接近峰值。反之，若路由分布随请求类型剧烈变化（长尾专家频繁被激活、单请求命中专家数方差大），片上占用核算会反复失效，溢出风险与不可观测性叠加，此时应保留多 kernel 流水作为兜底路径，并把 mega-kernel 作为可开关的快路径——按路由熵或单 micro-batch 激活专家数设阈值切换，让配方在边界内收益、边界外可控退化。</p>\n<h3 id=\"alg-monomoe-fused-kernel-sec-31\">三十一 · 融合核的代价结构：从“省掉什么”到“多出什么”</h3>\n<p>讨论 mega-kernel 的系统代价，先要把账算清楚：它省掉的是 kernel launch 与中间缓冲的 HBM 往返，多出来的是常驻 SM 的资源占用、shared memory 的容量压力，以及一条难以切分的执行路径。前几节已给出融合后的时延近似式 $T_{\\text{fused}} \\approx \\max(B_w/\\text{BW}_{\\text{HBM}},\\ T_{\\text{MMA}}) + T_{\\text{epilogue}}$，这个式子的结构本身就说明了代价所在：它把 decode 时延压成“权重带宽”与“MMA 时间”两条腿的较大者，再加一个 epilogue。多 kernel 版本则是把 dispatch、反量化、分组 GEMM、combine 各自的 HBM 读写与 launch 开销逐段相加，小 batch 下这些段开销占比超过 50%。因此融合核的收益不是“让计算变快”，而是把一段串行的、以字节搬运和调度为主的开销折叠进一条流水线。</p>\n<p>代价的第一层是常驻占用。mega-kernel 启动后常驻 SM，从全局队列逐个取 micro-batch 的路由结果，这意味着 SM 的寄存器与 shared memory 在整个 decode 期间被这条流水线持有，不能像多 kernel 那样在段与段之间把资源还给调度器。第二层是 shared memory 容量：反量化与 token 重排在 shared memory 内完成，权重 tile、激活 tile、重排后的 token 缓冲要同时驻留；容量不足时溢出到 HBM，融合收益被直接抵消——这是材料明确列出的失败模式。第三层是可见性：融合后调试与 profiling 困难，路由分布突变时无法定位是哪个阶段退化，因为整条路径只有一个 kernel 边界。</p>\n<p>具体例子：一个 micro-batch 的路由结果指向若干激活专家，TMA 异步把 NVFP4/INT4 量化权重从 HBM 搬到 shared memory，与 tcgen05 异步 MMA 流水重叠；若某个专家的权重 tile 加上重排缓冲超出 shared memory 预算，反量化就会退回 HBM 往返，此时 $B_w/\\text{BW}_{\\text{HBM}}$ 项不变但多了一次写回与再读，实际时延向多 kernel 版本回退。工程判断因此很直接：融合核的容量规划不是“能放下就放”，而是按最坏路由分布下的同时激活专家数预留 shared memory。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-32\">三十二 · 带宽账：权重字节是分子，micro-batch 是分母</h3>\n<p>在 decode 阶段，每生成一个 token 要把激活专家的量化权重完整读一遍，因此权重字节 $B_w$ 是带宽账的分子，而每次 kernel 迭代处理的 token 数（micro-batch 大小）是分母。融合核把多个 micro-batch 串在同一个常驻 kernel 里依次处理，权重加载与 MMA 通过 TMA 与 tcgen05 流水重叠，于是单 token 摊到的权重带宽成本取决于流水线能否把 $B_w/\\text{BW}_{\\text{HBM}}$ 隐藏在 $T_{\\text{MMA}}$ 之下。当 $B_w/\\text{BW}_{\\text{HBM}} &gt; T_{\\text{MMA}}$ 时，这条流水线是带宽受限的，GPU 利用率的上限由 HBM 带宽决定，MMA 单元有空转；反之则是计算受限。</p>\n<p>这里有一个容易被忽略的规模效应：micro-batch 越小，$T_{\\text{MMA}}$ 越短，越容易落进带宽受限区，融合核的收益越大；micro-batch 越大，GEMM 计算占比上升，launch 开销被摊薄，多 kernel 版本的相对劣势缩小，融合核的边际收益下降。这正是适用边界所写的“收益随 batch 增大而下降”。因此带宽账不能只看单次迭代，要看在目标 SLO 下 micro-batch 落在哪个区间。</p>\n<p>具体机制上，TMA 把权重从 HBM 搬进 shared memory 的动作与 MMA 并行，反量化在 shared memory 内就地完成，不产生额外的全局读写；combine 在寄存器内按路由权重累加，不落 HBM。这三处叠加，使得融合核的全局字节流量接近“只读权重 + 只写输出”，而多 kernel 版本还要加上 dispatch 缓冲、反量化输出、GEMM 中间结果、combine 输入的多次往返。定性地说，融合核把 HBM 流量从“每段一次往返”压到“每 token 一次权重读加一次输出写”，这是带宽账上最实质的改善。</p>\n<p>代价侧的例子：若路由分布突变导致同时激活的专家数上升，$B_w$ 随之上升而 $T_{\\text{MMA}}$ 未必同比例上升，流水线从计算受限滑向带宽受限，此时即使融合核消除了 launch 开销，单 token 时延仍会被权重带宽顶住。工程上应对这一点的办法不是加大 micro-batch，而是让权重加载的 tile 粒度与专家粒度对齐，避免为少量 token 拉取整个专家权重。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-33\">三十三 · 通信账：融合核把 All-to-All 的边界推到 kernel 之外</h3>\n<p>在专家并行部署下，dispatch 与 combine 本质上是 token 在设备间的搬运，即 All-to-All。融合核把 dispatch、反量化、分组 GEMM、combine 收进一个 kernel，意味着 All-to-All 的接收侧必须在这条常驻流水线里完成，而不是作为一个独立的通信 kernel 与计算 kernel 交替。这带来两个系统代价：其一，通信与计算的重叠窗口被压缩进同一条流水线，NVLink 5 上的传输必须与 TMA 权重加载、tcgen05 MMA 共享流水资源；其二，路由结果的全局队列成为跨设备同步点，micro-batch 的取用节奏受最慢那个 rank 的 All-to-All 完成时间约束。</p>\n<p>用公式表达这种约束：单次迭代的时延下界是 $\\max(T_{\\text{fused}},\\ T_{\\text{A2A}})$，其中 $T_{\\text{A2A}}$ 是该 micro-batch 的 All-to-All 时间。融合核把 $T_{\\text{fused}}$ 压得很低时，$T_{\\text{A2A}}$ 就会成为新的瓶颈——这正是“规模上去以后哪里先崩”的第一个候选答案：在小 batch、单机或低并行度下先崩的是 launch 与 HBM 往返；并行度上去、跨机比例上升后，先崩的变成通信。</p>\n<p>具体例子：一个 micro-batch 的路由结果分散到多个专家并行 rank，每个 rank 上的融合核等待本 rank 的 token 到齐后才开始 TMA 加载权重。若某个 rank 的 All-to-All 因链路拥塞晚到，其余 rank 的常驻 kernel 只能空转等待，SM 被占用却不产出。这与多 kernel 版本不同：多 kernel 版本可以在等待通信时让出 SM 给别的 kernel，而常驻 kernel 的占用是持续的。因此融合核在分离式专家并行下的部署，必须把 micro-batch 的取用做成有界队列，用队列深度吸收通信抖动，而不是让 kernel 直接阻塞在单个 micro-batch 上。</p>\n<p>代价的定性表述：融合核减少了设备内的字节搬运，却把设备间的通信暴露为不可隐藏的串行段；并行度越高、专家越分散，这部分占比越大。工程判断是：融合核适合与通信调度协同设计，让 All-to-All 的完成事件驱动全局队列的取用，而不是让 kernel 内部自旋等待。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-34\">三十四 · 功耗与占用：常驻 SM 的代价不是免费的</h3>\n<p>常驻 SM 的 mega-kernel 在 decode 全程保持活跃，即使某个 micro-batch 的 MMA 流水因等待权重或等待通信而空转，SM 的时钟与供电也不会回落。这与多 kernel 版本形成对比：多 kernel 在段与段之间有空隙，GPU 可以在空隙里降频或让其他工作插入。融合核把这部分空隙吃掉，换来的是更低的时延，付出的是更高的持续功耗与更差的能效曲线在低负载区的表现。</p>\n<p>从公式看，$T_{\\text{fused}}$ 中的 $\\epsilon_{\\text{launch}}$ 被压到趋近于零（persistent），但代价是 kernel 内部的自旋与轮询本身要耗电。tcgen05 异步 MMA 与 TMA 的重叠让计算单元与搬运单元同时工作，峰值功耗高于串行执行；在带宽受限区，MMA 单元空转但仍被时钟驱动，这部分功耗不产生有效吞吐。因此融合核的能效优势出现在流水线饱满的区间，而在路由稀疏、micro-batch 很小的区间，能效可能不如多 kernel 版本——虽然后者时延更差。</p>\n<p>具体机制上，功耗代价与 shared memory 容量压力耦合：为了把反量化与 token 重排留在 shared memory，需要更大的 shared memory 分配，这限制了每个 SM 上可并发的常驻 kernel 数量，也限制了用更多并发来掩盖延迟的手段。工程上常见的取舍是减小权重 tile 以换取更多并发，但这会拉长 $B_w/\\text{BW}_{\\text{HBM}}$ 的有效传输时间，把流水线推向带宽受限。这个取舍没有普适解，要按目标 SLO 下的 micro-batch 分布来定。</p>\n<p>例子：在低 QPS 的在线服务里，请求到达稀疏，micro-batch 长期处于很小值，融合核的常驻 SM 持续耗电而吞吐上不去；此时若按峰值能效配置容量，会在低负载区浪费功耗预算。容量规划应把融合核的功耗曲线按负载区间分段计入，而不是只按峰值吞吐折算。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-35\">三十五 · 尾延迟：融合核把抖动集中到一个不可分割的段</h3>\n<p>尾延迟是融合核最容易被低估的代价。多 kernel 版本里，一段变慢只影响该段的时延，调度器可以在段间重新排序、插入其他请求；融合核把整条路径收进一个 kernel，任何一个 micro-batch 的异常——路由分布突变导致同时激活专家数暴增、某个专家的权重 tile 超出 shared memory 预算触发溢出、某个 rank 的 All-to-All 晚到——都会把整条流水线拖住，且没有 kernel 边界可供调度器介入。</p>\n<p>用排队论的语言：融合核把服务时间从“多段独立随机变量之和”变成“单段取最大值的随机变量”，$T_{\\text{fused}} \\approx \\max(B_w/\\text{BW}_{\\text{HBM}},\\ T_{\\text{MMA}}) + T_{\\text{epilogue}}$ 中的 max 使得时延分布的上尾由两条腿中较慢的那条决定，而不是两条腿的平均。这意味着 P99 时延对路由分布的尾部敏感度高于多 kernel 版本。材料明确指出融合后路由分布突变时无法定位退化阶段，这不仅是调试问题，也是尾延迟治理问题：你不知道是带宽腿还是 MMA 腿在拖尾。</p>\n<p>具体机制上的缓解手段是给全局队列设界并做 micro-batch 级的准入：当某个 micro-batch 的激活专家数超过 shared memory 预算时，不把它塞进当前流水线，而是拆成更小的 micro-batch 分次处理，用更多的迭代次数换取单次迭代的可预测性。代价是 launch 开销的收益被部分回吐，但在尾延迟敏感的 SLO 下这是必要的。另一个手段是在 epilogue 里把寄存器累加与写回做成非阻塞，让 $T_{\\text{epilogue}}$ 不随输出规模线性增长。</p>\n<p>例子：在线服务要求 P99 控制在某个预算内，而平均时延远低于预算；此时融合核的平均时延优势可能被尾延迟抵消。工程判断是：融合核的部署要配尾延迟观测，按 micro-batch 记录 $B_w/\\text{BW}_{\\text{HBM}}$ 与 $T_{\\text{MMA}}$ 的实测分解，才能在路由突变时判断是哪条腿越界。这需要在 kernel 内埋点，而埋点本身与“融合后 profiling 困难”相冲突，是这套方案的结构性代价。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-36\">三十六 · 规模上去以后哪里先崩：一条按规模排序的崩溃链</h3>\n<p>把上述几条账按规模排序，可以得到一条相对清晰的崩溃链。第一层是小 batch、单设备：先崩的是 kernel launch 与中间缓冲的 HBM 往返，这正是融合核要解决的问题，收益 30–50% 的时延下降落在这里。第二层是 shared memory 容量：随着同时激活专家数上升，权重 tile 加重排缓冲超出预算，反量化溢出到 HBM，融合收益被抵消，此时崩溃表现为“融合了但没快”。第三层是并行度与跨机通信：专家并行度上去后，$T_{\\text{A2A}}$ 超过 $T_{\\text{fused}}$，常驻 kernel 空转等待，崩溃表现为 SM 占用高而吞吐不涨。第四层是尾延迟与功耗：在低负载或路由突变区间，常驻 SM 的持续占用与不可分割的执行段让 P99 与能效同时恶化。</p>\n<p>这条链的工程含义是：融合核不是一个可以无差别铺开的优化，它的收益区间有明确的上界和下界。上界由 shared memory 容量与路由分布决定，下界由 micro-batch 大小与 SLO 决定。容量规划时应把“融合核收益”写成关于 micro-batch 与激活专家数的函数，而不是一个固定百分比。材料给出的 30–50% 时延下降是在小 batch decode 场景下的定性区间，超出这个场景就不能直接套用。</p>\n<p>具体机制上，判断当前落在哪一层崩溃，可以看两个比值：$B_w/\\text{BW}_{\\text{HBM}}$ 与 $T_{\\text{MMA}}$ 的比值告诉你是否带宽受限；$T_{\\text{fused}}$ 与 $T_{\\text{A2A}}$ 的比值告诉你通信是否已经成为瓶颈。前者大于 1 说明权重带宽是腿，后者大于 1 说明 All-to-All 是腿。两个比值都小于 1 时，融合核才真正跑在流水线饱满的区间，此时它的 launch 消除与 HBM 往返消除才是净收益。工程判断落在具体机制上：把这两个比值做成部署时的常驻观测指标，按 micro-batch 滚动更新，比任何静态容量公式都更能反映“哪里先崩”。</p>\n<p>最后一点是移植成本，它不属于运行时崩溃链，但决定了这套方案能否在规模上复制：mega-kernel 需手写 PTX/CUDA 并绑定 SM100/SM103 的 TMA 与 tcgen05 指令，跨架构移植成本极高。规模上去以后，真正先崩的往往不是某一个硬件资源，而是“每换一代架构就要重写一遍融合核”的工程组织能力——这条代价不在公式里，但在部署配方里是硬约束。</p>\n<h3 id=\"alg-monomoe-fused-kernel-sec-37\">三十七 · 精度失效的三条路径与定点观测</h3>\n<p>mega-kernel 把反量化搬进 shared memory、把 combine 搬进寄存器，精度问题不再表现为某个独立 kernel 的输出偏差，而是沿着三条路径悄悄累积。第一条是权重微缩放因子在 TMA 搬运后被复用错位：同一专家被多个 micro-batch 命中时，若缩放因子缓存未按专家版本刷新，NVFP4/INT4 的 block scale 会张冠李戴，误差在分组 GEMM 内被放大。第二条是 shared memory 内反量化与 token 重排共用缓冲区，重排写回与反量化读入若缺少显式同步，会出现半量化值参与 MMA。第三条是寄存器累加的 combine 权重在 FP32 与低精度之间往返，累加顺序随路由分布变化，导致同一 token 在不同 micro-batch 上得到数值不一致的输出。</p>\n<p>诊断不能靠端到端 loss 或困惑度，那已被下游层稀释。可行做法是在 mega-kernel 的 epilogue 处埋点，按专家维度统计输出张量的相对误差与饱和比例：</p>\n<div class=\"formula\">$$\\delta_e=\\frac{\\lVert y_e-\\hat y_e\\rVert_2}{\\lVert y_e\\rVert_2},\\quad \\text{satur}_e=\\frac{\\#\\{|x|&gt;x_{\\max}\\}}{\\#\\{x\\}}$$</div>\n<p>其中 $y_e$ 为参考高精度路径输出，$\\hat y_e$ 为融合路径输出。$\\delta_e$ 按专家聚合后若出现少数专家显著高于中位数，基本可判定为缩放因子错位而非全局量化噪声；$\\text{satur}_e$ 偏高则指向激活量化区间与权重不匹配。代价上，这类埋点必须落在寄存器写回前的 epilogue，否则中间结果已落 HBM，观测本身就把融合收益吃掉；工程上以采样方式每 N 个 micro-batch 打开一次，避免常驻开销侵蚀 decode 时延。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-38\">三十八 · OOM 与 shared memory 溢出的判别</h3>\n<p>融合大核的 OOM 有两类，处置方式完全不同。第一类是显存 OOM：分页 KV 与专家权重共存时，mega-kernel 常驻 SM 意味着它持有的权重分片与工作缓冲在 kernel 生命周期内不释放，若调度器同时抬高并发 micro-batch 数，权重驻留与 KV 页会争抢同一池。判别方法是看 OOM 发生时是否伴随权重加载 TMA 的重复次数上升——重复加载说明权重被换出又换入，属于驻留策略失效而非单纯容量不足。第二类是 shared memory 溢出：反量化与 token 重排的临时缓冲超过单 SM 可用 shared memory 时，编译器会把溢出部分落到 HBM，此时不报 OOM，但融合收益被抵消。前文公式中的 $T_{\\text{epilogue}}$ 会异常抬升，而 $\\text{BW}_{\\text{HBM}}$ 项不变，形成“带宽没打满、时延却上不去”的特征。</p>\n<p>监控手段是在 kernel 内读取 shared memory 占用与溢出计数的硬件计数器，按 SM 聚合后与理论需求比对。工程判断上，溢出一旦确认，优先缩小单 micro-batch 的 token 重排窗口，而不是降低量化位宽——后者会引入新的精度路径问题。显存侧则把权重驻留与 KV 页的配额显式分离，避免调度器在批抖动时把两者混算。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-39\">三十九 · 批抖动与路由不均的耦合诊断</h3>\n<p>批抖动在融合核里表现得很隐蔽：micro-batch 从全局队列逐个取，队列深度变化不会立刻反映为时延，因为常驻 SM 会持续消费。真正的抖动来自路由分布突变——某几个专家在连续 micro-batch 中被集中命中，TMA 加载的权重量骤增，而其他专家的 MMA 流水空转。此时 $T_{\\text{fused}}$ 的 max 项从 MMA 侧切到带宽侧，表现为吞吐台阶式下跌而非平滑劣化。判别指标是按专家统计的 token 命中率方差与 TMA 加载字节数的滑动窗口比值：比值突增说明路由集中度上升，带宽项开始主导。</p>\n<p>路由不均还会与容量因子策略相互作用，但那属于路由侧议题，此处只关注它对融合核的观测影响。诊断上应在 dispatch 入口记录每个专家的 token 计数直方图，与 MMA 占用率对齐时间轴；若直方图尖峰与 MMA 占用率低谷同相，即可确认是路由不均而非 kernel 实现退化。代价是直方图统计本身需要一次全局归约，放在 micro-batch 边界做，避免打断流水。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-40\">四十 · 尾延迟尖刺的定位顺序</h3>\n<p>尾延迟尖刺在融合核中有三个高频来源，定位必须按代价从低到高排序。先查 launch 边界：persistent kernel 本应消除重复 launch，但若队列取数逻辑在空队列时退出并重新启动，$\\epsilon_{\\text{launch}}$ 会以尖刺形式回归，表现为 P99 与 P50 的巨大落差而均值正常。再查 TMA 与 MMA 的流水断点：权重加载与 MMA 重叠依赖异步屏障，若某 micro-batch 的专家集合跨越多个权重块，屏障等待会串行化，尖刺出现在专家切换点。最后查 epilogue 的寄存器压力：combine 累加在寄存器内完成，寄存器溢出会导致局部 spill，尖刺与特定路由权重分布相关。</p>\n<p>定位顺序的依据是观测成本：launch 边界只需在 kernel 入口与出口打时间戳，流水断点需要 TMA 屏障计数器，寄存器 spill 需要编译期与运行期双重确认。工程上先排除前两者再动编译器选项，避免把实现问题误判为容量问题。尾延迟尖刺若与路由直方图尖峰同相，则应回到上一节的诊断路径，而不是在 kernel 内继续加埋点。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-41\">四十一 · 监控面与回滚判据</h3>\n<p>融合核的监控面必须窄而有针对性，否则 profiling 本身成为负担。建议维持四个常驻指标：按专家的 $\\delta_e$ 采样、shared memory 溢出计数、TMA 加载字节与 MMA 占用率的比值、micro-batch 边界时间戳的 P99。这四个指标分别对应精度、溢出、路由不均与 launch 尖刺，覆盖了前四节的全部失败模式。指标采集点全部落在 micro-batch 边界或 epilogue，不进入 MMA 主循环。</p>\n<p>回滚判据要写成可执行的阈值组合而非单一指标。精度侧：$\\delta_e$ 的专家间离散度超过基线一定倍数且持续多个采样窗口，回滚到多 kernel 流水路径。溢出侧：溢出计数非零即回滚或缩窗口，因为溢出直接抵消融合收益。路由侧：TMA 与 MMA 比值突增但专家直方图未变，说明是权重驻留问题而非路由问题，应先调驻留策略再考虑回滚。launch 侧：P99 尖刺与队列空转同相，修取数逻辑而非回滚。回滚路径本身要保留多 kernel 版本作为对照，因为融合核与多 kernel 流水共享同一套路由与量化格式，切换成本主要在调度层而非模型层。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>观测点</th><th>判别特征</th><th>处置</th></tr></thead><tbody><tr><td>缩放因子错位</td><td>epilogue 按专家 $\\delta_e$</td><td>少数专家离散度高</td><td>刷新专家版本缓存</td></tr><tr><td>shared memory 溢出</td><td>SM 溢出计数</td><td>带宽未满、时延不降</td><td>缩 token 重排窗口</td></tr><tr><td>路由不均</td><td>专家直方图与 MMA 占用率</td><td>尖峰与低谷同相</td><td>调驻留与队列深度</td></tr><tr><td>launch 尖刺</td><td>micro-batch 边界时间戳</td><td>P99 落差、均值正常</td><td>修队列取数逻辑</td></tr></tbody></table>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-42\">四十二 · 跨架构移植与调试成本的工程判断</h3>\n<p>mega-kernel 绑定 SM100/SM103 的 TMA 与 tcgen05 指令，跨架构移植不是改编译选项而是重写流水。移植失败的典型症状是 TMA 描述符与 shared memory 布局不匹配，表现为加载正确但 MMA 读到错位数据，精度指标正常而输出语义错误——这类问题无法用 $\\delta_e$ 捕获，只能靠小规模确定性用例逐块比对。工程判断上，把融合核视为架构专属资产，回滚与对照始终保留多 kernel 路径，避免把可移植性押在单一指令集上。</p>\n<p>调试成本的另一面是 profiling 工具对 persistent kernel 的支持有限：常驻 SM 使传统按 kernel 粒度的计时失效，必须依赖 kernel 内埋点与硬件计数器。因此监控面的设计要先于 kernel 实现定稿，把观测点当作接口而非事后补丁。最终落在具体机制上：epilogue 处的按专家误差采样与 micro-batch 边界时间戳，是这套融合核唯一可靠的退化定位手段，其余指标都是它们的推论。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-43\">四十三 · 融合核的失效边界：从精度漂移、显存溢出到尾延迟尖刺</h3>\n<p>mega-kernel 把 dispatch、反量化、分组 GEMM、combine 收进一个常驻 SM 的循环体，收益来自把中间缓冲留在 shared memory 与寄存器。代价是：一旦某个阶段的资源假设被打破，退化不会以“某个 kernel 变慢”的形式暴露，而是整体塌陷。最典型的失效是 shared memory 容量不足——反量化后的激活分块、token 重排索引、按路由权重累加的寄存器暂存三者叠加，若超过单 SM 可用 shared memory，编译器或手写代码只能把部分中间结果溢出到 HBM，此时融合收益被抵消，$T_{\\text{fused}}$ 中的 $T_{\\text{epilogue}}$ 项急剧膨胀，实测表现是吞吐回到多 kernel 流水水平甚至更差。诊断方法是给每个 micro-batch 记录 shared memory 占用峰值与溢出字节数，把溢出计数作为一级指标而非事后归因。</p>\n<p>精度问题在融合核里更难定位，因为反量化、重排、MMA、累加四步共享同一段寄存器生命周期，误差来源被压扁。NVFP4/INT4 权重的块缩放因子在 shared memory 内反量化时若与 token 重排顺序错位，误差不会报错，只会表现为输出分布的细微偏移；而 combine 不落 HBM、直接在寄存器内按路由权重累加，意味着累加顺序随路由分布变化，浮点非结合性带来的偏差随专家数上升。工程上应固定一条参考路径（同一 micro-batch 走多 kernel 版本）做逐层比对，把“融合核输出与参考输出的相对误差”作为回归门禁，而不是等端到端评测发现质量下降。代价是这条参考路径本身占用额外显存与算力，只能在离线或影子流量中跑。</p>\n<p>路由不均与批抖动是同一枚硬币的两面。mega-kernel 从全局队列逐个取 micro-batch 的路由结果，队列的填充速率由上游调度器决定；当路由分布突变（某几个专家被集中命中），TMA 加载的权重字节数 $B_w$ 在 micro-batch 之间剧烈波动，$T_{\\text{fused}}\\approx\\max(B_w/\\text{BW}_{\\text{HBM}},T_{\\text{MMA}})+T_{\\text{epilogue}}$ 的瓶颈项在带宽与 MMA 之间来回切换，SM 常驻循环出现空转等待。表现为 P99 尾延迟尖刺，而均值吞吐看似正常。监控上应对每个 micro-batch 记录专家命中直方图的熵、$B_w$ 实际值与 MMA 占用率，三者同时下钻才能区分“路由突变”与“TMA 流水断流”。</p>\n<p>OOM 与回滚策略需要按层次设计。融合核的显存占用由权重常驻、shared memory 分块、输出缓冲三部分构成，其中权重以 NVFP4/INT4 格式存放，压缩率高但反量化后的临时缓冲不可压缩；当并发 micro-batch 数上升或专家数扩张，最先触顶的是临时缓冲而非权重。回滚不应是“关掉融合核”这一粗粒度动作，而应分级：先降 micro-batch 并发深度，再退回多 kernel 流水，最后回退到未量化的参考路径。跨架构移植成本极高——mega-kernel 绑定 SM100/SM103 的 TMA 与 tcgen05 指令，手写 PTX/CUDA 无法在别的架构上直接复用，因此回滚预案必须在部署前就与主路径一同验证，而不是等故障时临时拼装。适用边界也应写进容量规划：收益随 batch 增大而下降，大 batch 下 GEMM 计算占比上升、launch 开销被摊薄，此时融合核的复杂度不再换来时延，反而放大调试成本。</p>\n<h3 id=\"alg-monomoe-fused-kernel-sec-44\">四十四 · 决策轴：先分清“谁在等谁”</h3>\n<p>把融合大核放进同族算法的坐标系里，第一步不是比性能，而是判断当前 decode 的瓶颈归属。同族算法大致分四类：多 kernel 流水（路由 / dispatch / 反量化 / 分组 GEMM / combine 各自成核）、无丢弃块稀疏分组 GEMM、专家选择路由配合容量因子丢弃、以及本片段的 persistent 融合 mega-kernel。它们的差别不在数学，而在“中间缓冲落在哪一级存储”和“控制流由谁承担”。多 kernel 流水把中间结果写回 HBM，靠 host 或 device 端逐个 launch 推进；融合大核把 dispatch、反量化、分组 GEMM、combine 收进一个常驻 SM 的 kernel，中间结果留在 shared memory 与寄存器，控制流由 kernel 内部的全局队列驱动。</p>\n<p>判断依据可以直接落在时延公式上：</p>\n<div class=\"formula\">$$T_{\\text{decode}}\\approx\\max\\left(\\frac{\\sum_e |W_e|\\cdot b_w}{\\text{BW}},\\ \\frac{\\text{FLOPs}}{\\text{FLOPs}_{\\text{peak}}}\\right)+\\epsilon_{\\text{launch}},\\quad \\epsilon_{\\text{launch}}\\to 0\\ \\text{(persistent)}$$</div>\n<p>式中第一项是权重字节除以显存带宽，第二项是计算量除以峰值算力。多 kernel 流水下 $\\epsilon_{\\text{launch}}$ 是每个 kernel 的 launch 开销加上中间缓冲的 HBM 往返，小 batch 时这两项合计占比超过 50%，于是 $\\epsilon_{\\text{launch}}$ 不可忽略；融合大核把它压到接近零，代价是把复杂度全部转移到 kernel 内部。因此决策的第一问是：当前 batch 下 $\\epsilon_{\\text{launch}}$ 是否仍是主导项。若权重加载项已经主导（大 batch、GEMM 计算占比上升），融合带来的收益被摊薄，多 kernel 流水反而更容易维护。</p>\n<p>第二问是路由分布是否稳定。融合大核把反量化与 token 重排在 shared memory 内一次完成，路由突变时无法从外部区分是 dispatch 阶段还是 GEMM 阶段退化——这是它的固有诊断盲区。若线上流量路由熵高、专家命中频繁抖动，保留分阶段 kernel 的可观测性比省下几十微秒更值。第三问是架构绑定：mega-kernel 需手写 PTX/CUDA 并针对 SM100/SM103 的 TMA 与 tcgen05 指令定制，跨架构移植成本极高，只有确定长期锁定 Blackwell 的部署才值得投入。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-45\">四十五 · 对照表：四类同族算法的适用条件</h3>\n<table class=\"mini\">\n<thead>\n<tr><th>算法族</th><th>中间结果落点</th><th>主导开销</th><th>适用条件</th><th>不适用信号</th></tr>\n</thead>\n<tbody>\n<tr><td>多 kernel 流水</td><td>HBM 中间缓冲</td><td>launch + HBM 往返</td><td>大 batch、路由抖动、需分阶段 profiling</td><td>小 batch 下 $\\epsilon_{\\text{launch}}$ 占比过半</td></tr>\n<tr><td>无丢弃块稀疏分组 GEMM</td><td>HBM / shared</td><td>分组 GEMM 与块稀疏索引</td><td>不允许丢 token、专家负载可分组均衡</td><td>块稀疏粒度与专家粒度不匹配</td></tr>\n<tr><td>专家选择路由 + 容量因子丢弃</td><td>HBM</td><td>路由与丢弃判定</td><td>吞吐优先、可容忍少量 token 降级</td><td>质量敏感、长尾 token 不可丢</td></tr>\n<tr><td>persistent 融合 mega-kernel</td><td>shared memory / 寄存器</td><td>权重带宽与 MMA 流水</td><td>小 batch、带宽受限、锁定 SM100/SM103</td><td>shared memory 不足、跨架构部署</td></tr>\n</tbody>\n</table>\n<p>表中第三列是选型的锚点。融合大核的时延近似为</p>\n<div class=\"formula\">$$T_{\\text{fused}} \\approx \\max\\left(\\frac{B_w}{\\text{BW}_{\\text{HBM}}},\\ T_{\\text{MMA}}\\right) + T_{\\text{epilogue}}$$</div>\n<p>$B_w$ 是权重字节数，$T_{\\text{MMA}}$ 是矩阵乘时间，$T_{\\text{epilogue}}$ 是寄存器累加与写回时间。这个式子说明融合大核的天花板由权重带宽决定：NVFP4/INT4 量化把 $B_w$ 压到低位宽，才让 $\\frac{B_w}{\\text{BW}_{\\text{HBM}}}$ 落到与 $T_{\\text{MMA}}$ 同一量级，TMA 异步加载与 tcgen05 异步 MMA 的流水重叠才有意义。若权重仍是 FP8 或 BF16，带宽项远大于 MMA 项，融合省下的 launch 开销被权重搬运淹没，收益不成立。</p>\n<p>与无丢弃块稀疏分组 GEMM 的分工要看清：后者解决的是“不丢 token 前提下如何把分组 GEMM 做规整”，它的中间结果仍可能落 HBM；融合大核解决的是“中间结果根本不落 HBM”。两者可以叠加——块稀疏分组 GEMM 作为 mega-kernel 内部的 MMA 形态，但此时 shared memory 预算要同时容纳反量化后的权重块、token 重排缓冲与块稀疏索引，容量压力陡增。与专家选择路由配合容量因子丢弃相比，融合大核不做丢弃决策，它假设路由结果已经确定并从全局队列取用，因此丢弃策略的收益与它的收益互不冲突，但也互不补偿。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-46\">四十六 · 选型伪代码：按序排除而非按分排序</h3>\n<p>工程上不要给四类算法打分求和，而应按硬约束逐条排除，因为融合大核的失败是“不可用”而非“慢一点”。</p>\n<ul>\n<li>若部署目标包含非 Blackwell 架构，直接排除 mega-kernel：手写 PTX 绑定 SM100/SM103 的 TMA 与 tcgen05 指令，移植成本高于收益。</li>\n<li>若单卡 shared memory 预算无法同时容纳反量化权重块、token 重排缓冲与累加暂存，排除融合路径——容量不足时反量化与 token 重排会溢出到 HBM，抵消全部融合收益。</li>\n<li>若 batch 已大到 GEMM 计算项超过权重带宽项，融合的边际收益趋近于零，选多 kernel 流水以保留可观测性。</li>\n<li>若质量约束禁止丢 token，在剩余候选中优先块稀疏分组 GEMM 而非容量因子丢弃。</li>\n<li>剩余候选才进入性能比较，此时融合大核在小 batch、带宽受限场景下时延可降低 30–50%，是默认选择。</li>\n</ul>\n<p>伪代码层面的判断可以写成一次静态检查加一次运行时采样：静态检查架构与 shared memory 上限；运行时采样连续若干 micro-batch 的 $\\frac{B_w}{\\text{BW}_{\\text{HBM}}}$ 与 $T_{\\text{MMA}}$ 估计值，若前者持续大于后者，说明仍处带宽受限区，融合有效；若后者反超，说明已进入计算受限区，应回退。这个采样不需要精确数值，只需比较两个量的相对大小，避免了对峰值算力的过度依赖。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-47\">四十七 · 代价对照：延迟、吞吐、显存、带宽与功耗</h3>\n<p>融合大核的延迟收益来自消除 launch 与 HBM 往返，小 batch 下时延降低 30–50%；吞吐收益来自 TMA 与 tcgen05 异步流水重叠权重加载与 MMA，带宽受限场景下 GPU 利用率接近峰值。显存侧的收益是隐性的：中间缓冲不再需要 HBM 驻留，省下的是 dispatch 输出、反量化结果、combine 输入这几块按 token 数乘以隐藏维度的缓冲，batch 越小省得越少，但省下的是“峰值占用”而非均值，对分页 KV 与专家权重共存的显存预算有实际帮助。带宽侧则是把多次 HBM 读写压缩为一次权重读入加一次输出写回。</p>\n<p>代价集中在工程侧而非运行侧。实现复杂度极高，需手写 PTX/CUDA 并针对 SM100/SM103 定制；融合后调试与 profiling 困难，路由分布突变时难以定位是哪个阶段退化。功耗方面，persistent kernel 常驻 SM 意味着空转期间仍有静态功耗，micro-batch 队列枯竭时不会像多 kernel 流水那样自然回落，因此队列深度必须足够，否则常驻带来的功耗底噪会侵蚀收益。这一点在容量规划时容易被忽略：融合大核的能效优势只在队列持续有货时成立。</p>\n<p>具体例子：一个 NVFP4 量化的 MoE decode 服务，micro-batch 从全局队列逐个取，路由结果已由上游给出。多 kernel 流水下每个 micro-batch 要经历五次 launch 与四次中间缓冲 HBM 往返，小 batch 时这些开销占比过半；换成融合大核后，TMA 把激活专家的量化权重从 HBM 异步加载到 shared memory，与 tcgen05 MMA 流水重叠，反量化与 token 重排在 shared memory 内完成后直接喂给 MMA，MMA 结果在寄存器内按路由权重累加，combine 不落 HBM，输出写回全局显存后 kernel 继续处理下一 micro-batch。整条链路上只剩一次权重读入与一次输出写回，$\\epsilon_{\\text{launch}}$ 消失。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-48\">四十八 · 混合策略：把融合限制在它赢的那一段</h3>\n<p>实际部署很少全量替换。更稳的做法是按 batch 形态分段：小 batch 走融合大核，大 batch 走多 kernel 流水或块稀疏分组 GEMM，切换点由 $\\frac{B_w}{\\text{BW}_{\\text{HBM}}}$ 与 $T_{\\text{MMA}}$ 的相对大小决定。切换本身有代价——两条路径的权重布局与量化格式必须一致，否则切换时要做格式转换，反而引入新的 HBM 往返。因此混合策略的前提是权重统一为 NVFP4/INT4 量化格式，融合路径与非融合路径共享同一份权重。</p>\n<p>另一种混合是在融合大核内部保留可观测性：把 dispatch、反量化、GEMM、combine 各段的耗时以计数器形式写回全局显存的诊断缓冲，采样率可调，正常运行时关闭。这样路由分布突变时至少能定位退化阶段，缓解“融合后无法 profiling”的固有缺陷，代价是少量寄存器与分支开销。是否开启取决于线上路由熵的监控结果，而不是默认全开。</p>\n<p>与专家并行 All-to-All 调度的交界处要特别小心：融合大核假设路由结果已在本地全局队列中，跨节点 dispatch 仍由通信层完成，mega-kernel 只接管本地这一段。若把通信也塞进常驻 kernel，SM 会被通信等待占住，TMA 与 MMA 的流水反而被打断。因此选型时把“通信是否已在 kernel 外完成”作为前置条件，未满足则不进入融合路径。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-49\">四十九 · 工程判断：三条硬线</h3>\n<p>第一条硬线是架构锁定。mega-kernel 绑定 SM100/SM103 的 TMA 与 tcgen05 指令，跨架构移植成本极高，只有确定长期部署在 B200/B300、GB200/GB300 NVL72 上的服务才值得投入人力。第二条硬线是 shared memory 预算，容量不足时反量化与 token 重排溢出到 HBM，融合收益归零，这条线要在选型前用静态分析确认，而不是上线后靠 profiling 发现。第三条硬线是队列供给，persistent kernel 常驻 SM，micro-batch 队列枯竭时静态功耗照付，队列深度与到达率的匹配必须在容量规划阶段算清。</p>\n<p>三条线都满足时，融合大核在小 batch、带宽受限的量化 MoE decode 上是默认选择，时延降低 30–50% 的收益来自消除 launch 与 HBM 往返这一确定机制，而非调参运气。任一条不满足，就退回多 kernel 流水或块稀疏分组 GEMM，用可观测性换掉那几十微秒。选型的本质不是找最快的算法，而是确认当前瓶颈是否正好落在融合大核能消除的那一项上——$\\epsilon_{\\text{launch}}$ 与中间缓冲的 HBM 往返，仅此两项。</p>\n\n<h3 id=\"alg-monomoe-fused-kernel-sec-50\">五十 · 与相邻算法对照：同族算法怎么选</h3>\n<p>本方案并非量化 MoE decode 的唯一路径，同族至少还有两条：多 kernel 流水（dispatch、反量化、分组 GEMM、combine 各自独立，靠 CUDA Graph 压 launch 开销）与“半融合”方案（融合反量化与分组 GEMM，dispatch/combine 仍落 HBM）。三者的分界线是<strong>中间缓冲是否离开片上存储</strong>。多 kernel 流水每次都要把 dispatch 结果、反量化后的激活、GEMM 输出各写读一遍 HBM；半融合省掉反量化这一跳；mega-kernel 把四跳全砍掉，代价是整条流水必须在一个常驻 SM 的核内闭环。选型时先问一句：当前 decode 的瓶颈是 HBM 字节数还是 MMA 时间？用融合后的时延模型判断：</p>\n<div class=\"formula\">$$T_{\\text{fused}} \\approx \\max\\left(\\frac{B_w}{\\text{BW}_{\\text{HBM}}},\\ T_{\\text{MMA}}\\right) + T_{\\text{epilogue}}$$</div>\n<p>若 $B_w/\\text{BW}_{\\text{HBM}}$ 显著大于 $T_{\\text{MMA}}$，说明带宽受限，融合收益最大；若两者接近或 $T_{\\text{MMA}}$ 反超，说明计算占比上升，launch 与 HBM 往返已被摊薄，mega-kernel 的复杂度换不来时延。这就是收益随 batch 增大而下降的机理：micro-batch 变大后分组 GEMM 的有效计算量上升，$\\epsilon_{\\text{launch}}$ 在总时延中的份额被稀释。工程上可用一个粗判据：把多 kernel 流水实测的 launch + 中间缓冲往返时间除以端到端时延，若占比过半（材料给出的典型小 batch 情形即超过 50%），才值得上 mega-kernel；否则优先选半融合或多 kernel + CUDA Graph，把调试成本留在可控范围。</p>\n<table class=\"mini\"><thead><tr><th>方案</th><th>中间结果落点</th><th>适用条件</th><th>主要系统代价</th></tr></thead><tbody><tr><td>多 kernel 流水</td><td>HBM</td><td>大 batch、计算占比高、需快速迭代</td><td>launch 与 HBM 往返，小 batch 下占比过半</td></tr><tr><td>半融合（反量化+GEMM）</td><td>反量化后留在片上，dispatch/combine 落 HBM</td><td>中等 batch、路由分布稳定</td><td>两次 HBM 往返，实现难度中等</td></tr><tr><td>persistent mega-kernel</td><td>shared memory / 寄存器</td><td>小 batch、带宽受限、SM100/SM103 固定</td><td>手写 PTX/CUDA、调试困难、移植成本极高</td></tr></tbody></table>\n<p>三条失效条件必须写进选型清单。其一，<strong>架构绑定</strong>：mega-kernel 依赖 SM100/SM103 的 TMA 与 tcgen05 指令定制，跨架构移植成本极高，若部署池里混有 Hopper 或更早设备，同一份代码无法复用，只能按架构分叉维护。其二，<strong>可观测性塌陷</strong>：融合后路由分布突变（例如某专家突然承接大量 token）时，profiling 只能看到整核时延抬升，无法定位是 TMA 加载、反量化重排还是 epilogue 累加退化，排障从“看单个 kernel 指标”退化为“二分注释代码”。其三，<strong>shared memory 容量</strong>：反量化与 token 重排的工作集一旦超出片上容量就会溢出到 HBM，此时 $T_{\\text{fused}}$ 中的带宽项重新抬头，融合收益被抵消，且这种退化在代码里是静默的。因此该方案适合专家数适中、单专家权重切片能装进 shared memory、且硬件代际统一的推理集群；专家极多或权重切片偏大的模型，应先算清片上容量再决定是否融合。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2026 · NVFP4/FP8权重与激活量化</td></tr><tr><td>解决什么</td><td>量化 MoE decode 时路由、dispatch、反量化、分组 GEMM、combine 被拆成多个 kernel…</td></tr><tr><td>一句话机制</td><td>把路由后的 dispatch、NVFP4/INT4 反量化、分组 GEMM、combine 融合为单个 persist…</td></tr><tr><td>代价与失效</td><td>mega-kernel 实现复杂度极高，需手写 PTX/CUDA 并针对 SM100/SM103 的 TMA 与 tcgen05 指令定制…</td></tr><tr><td>后继</td><td></td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-monomoe-fused-kernel · 共 8 个片段</p>\n";break;}}})();
